CREATE OR REPLACE FUNCTION public._avancar_os_status(p_origem text, p_os_id uuid, p_alvo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    status_order TEXT[] := ARRAY['aberta','aprovada','programada','em_producao','em_cq','envase','aguardando_reserva','pronto_entrega','entregue','finalizada'];
    v_atual TEXT;
    v_idx_atual INT;
    v_idx_alvo INT;
    v_proximo TEXT;
    v_use_manual BOOLEAN;
BEGIN
    v_use_manual := p_origem IN ('manual','b2b');

    IF v_use_manual THEN
        SELECT status::text INTO v_atual FROM public.ordens_servico WHERE id = p_os_id;
    ELSE
        SELECT status::text INTO v_atual FROM public.ordens_servico_onfarm WHERE id = p_os_id;
    END IF;

    SELECT i INTO v_idx_atual FROM unnest(status_order) WITH ORDINALITY AS t(val,i) WHERE val = v_atual;
    SELECT i INTO v_idx_alvo FROM unnest(status_order) WITH ORDINALITY AS t(val,i) WHERE val = p_alvo;

    IF v_idx_atual IS NULL OR v_idx_alvo IS NULL THEN
        RAISE EXCEPTION 'Status OS inválido (% -> %).', v_atual, p_alvo;
    END IF;

    WHILE v_idx_atual < v_idx_alvo LOOP
        v_proximo := status_order[v_idx_atual + 1];
        IF v_use_manual THEN
            UPDATE public.ordens_servico SET status = v_proximo::public.status_os WHERE id = p_os_id;
        ELSE
            UPDATE public.ordens_servico_onfarm SET status = v_proximo::public.status_os_onfarm WHERE id = p_os_id;
        END IF;
        v_idx_atual := v_idx_atual + 1;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public._comunicacao_trg_os_onfarm_pronto_retirada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_idem text;
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status = 'pronto_entrega'::public.status_os_onfarm THEN
    v_idem := 'os_pronto_retirada:ordens_servico_onfarm:' || NEW.id::text;
    PERFORM public._comunicacao_publish_system_event(
      'produto_pronto_retirada','ordens_servico_onfarm', NEW.id, '{}'::jsonb, v_idem);
  END IF;
  RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION public._comunicacao_trg_os_pronto_retirada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_idem text;
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status = 'pronto_entrega'::public.status_os THEN
    v_idem := 'os_pronto_retirada:ordens_servico:' || NEW.id::text;
    PERFORM public._comunicacao_publish_system_event(
      'produto_pronto_retirada','ordens_servico', NEW.id, '{}'::jsonb, v_idem);
  END IF;
  RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION public._comunicacao_trg_portal_solicitacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ev text;
  v_transition text;
  v_idem text;
  v_status_ant text;
  v_status_novo text;
  v_first_assign boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_ev := 'solicitacao_criada';
    v_transition := 'insert';
    v_status_ant := NULL;
    v_status_novo := NEW.status::text;
    v_first_assign := (NEW.consultor_atribuido IS NOT NULL AND NEW.status = 'atribuida');
    -- Se INSERT já com status=atribuida, o evento canônico é solicitacao_criada
    -- (linha nova). A primeira atribuição via UPDATE é que precisa emitir
    -- 'solicitacao_atribuida' adicional; em INSERT, criada já é suficiente.
    v_first_assign := false;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      v_ev := CASE NEW.status
        WHEN 'atribuida' THEN 'solicitacao_atribuida'
        WHEN 'checkin_realizado' THEN 'solicitacao_checkin_realizado'
        WHEN 'em_visita' THEN 'solicitacao_em_visita'
        WHEN 'aguardando_os' THEN 'solicitacao_aguardando_os'
        WHEN 'concluida' THEN 'solicitacao_concluida'
        WHEN 'cancelada' THEN 'solicitacao_cancelada'
        ELSE NULL
      END;
      v_transition := 'status:' || COALESCE(NEW.status::text,'null');
      v_status_ant := OLD.status::text;
      v_status_novo := NEW.status::text;
    END IF;
    -- Primeira atribuição: consultor NULL→X. Deduplicação: se status já
    -- transicionou para 'atribuida' neste mesmo comando, o evento canônico
    -- já será emitido; não emitir de novo.
    IF OLD.consultor_atribuido IS NULL AND NEW.consultor_atribuido IS NOT NULL
       AND (v_ev IS DISTINCT FROM 'solicitacao_atribuida') THEN
      v_first_assign := true;
    END IF;
  END IF;

  IF v_ev IS NOT NULL THEN
    v_idem := 'solicitacao:' || encode(
      extensions.digest(
        concat_ws('|', v_ev, NEW.id::text, v_transition, COALESCE(NEW.updated_at::text,'')),
        'sha256'
      ), 'hex'
    );
    PERFORM public._comunicacao_publish_system_event(
      v_ev, 'portal_solicitacoes', NEW.id,
      jsonb_strip_nulls(jsonb_build_object(
        'solicitacao_id', NEW.id,
        'numero', NEW.numero_solicitacao,
        'cliente_id', NEW.cliente_id,
        'fazenda_id', NEW.fazenda_id,
        'tipo_demanda', NEW.tipo_demanda,
        'urgencia', NEW.urgencia,
        'status_anterior', v_status_ant,
        'status_novo', v_status_novo,
        'consultor_atribuido', NEW.consultor_atribuido,
        'origem_solicitacao', NEW.origem_solicitacao,
        'ocorrido_em', COALESCE(NEW.updated_at, now()),
        'transicao', v_transition
      )),
      v_idem
    );
  END IF;

  IF v_first_assign THEN
    v_idem := 'solicitacao:' || encode(
      extensions.digest(
        concat_ws('|','solicitacao_atribuida', NEW.id::text,
                  'first_assign:'||NEW.consultor_atribuido::text,
                  COALESCE(NEW.updated_at::text,'')),
        'sha256'
      ), 'hex'
    );
    PERFORM public._comunicacao_publish_system_event(
      'solicitacao_atribuida', 'portal_solicitacoes', NEW.id,
      jsonb_strip_nulls(jsonb_build_object(
        'solicitacao_id', NEW.id,
        'numero', NEW.numero_solicitacao,
        'cliente_id', NEW.cliente_id,
        'fazenda_id', NEW.fazenda_id,
        'tipo_demanda', NEW.tipo_demanda,
        'urgencia', NEW.urgencia,
        'status_novo', NEW.status::text,
        'consultor_atribuido', NEW.consultor_atribuido,
        'origem_solicitacao', NEW.origem_solicitacao,
        'ocorrido_em', COALESCE(NEW.updated_at, now()),
        'transicao', 'first_assign'
      )),
      v_idem
    );
  END IF;

  IF (TG_OP = 'INSERT' AND NEW.urgencia = 'critica')
     OR (TG_OP = 'UPDATE' AND NEW.urgencia = 'critica' AND OLD.urgencia IS DISTINCT FROM 'critica') THEN
    v_idem := 'solicitacao:' || encode(
      extensions.digest(
        concat_ws('|', 'solicitacao_urgencia_critica', NEW.id::text, 'urgencia:critica',
                  COALESCE(NEW.updated_at::text,'')),
        'sha256'
      ), 'hex'
    );
    PERFORM public._comunicacao_publish_system_event(
      'solicitacao_urgencia_critica', 'portal_solicitacoes', NEW.id,
      jsonb_strip_nulls(jsonb_build_object(
        'solicitacao_id', NEW.id,
        'numero', NEW.numero_solicitacao,
        'cliente_id', NEW.cliente_id,
        'fazenda_id', NEW.fazenda_id,
        'tipo_demanda', NEW.tipo_demanda,
        'urgencia', NEW.urgencia,
        'status_novo', NEW.status::text,
        'consultor_atribuido', NEW.consultor_atribuido,
        'origem_solicitacao', NEW.origem_solicitacao,
        'ocorrido_em', COALESCE(NEW.updated_at, now()),
        'transicao', 'urgencia:critica'
      )),
      v_idem
    );
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._rpc_avancar_esteira_laboratorio_internal(p_os_id uuid, p_origem_os text, p_etapa_destino text, p_programacao_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_role public.app_role;
    v_profile_id UUID;
    v_status_atual TEXT;
    v_lote_id UUID;
    v_etapa_anterior_os TEXT;
    v_tabela_os TEXT;
    v_validacao jsonb;
    v_cq_atual TEXT;
    v_status_alvo TEXT;
BEGIN
    SELECT role INTO v_user_role FROM public.user_roles WHERE user_id = auth.uid() LIMIT 1;
    SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1;

    IF p_origem_os IN ('manual','b2b') THEN v_tabela_os := 'ordens_servico';
    ELSE v_tabela_os := 'ordens_servico_onfarm';
    END IF;

    -- Status alvo canônico por etapa. 'criar_entrega' NAO tem status alvo:
    -- criar a entrega deixa a OS em pronto_entrega ate a confirmacao fisica.
    v_status_alvo := CASE p_etapa_destino
        WHEN 'assumir_producao' THEN 'em_producao'
        WHEN 'enviar_cq'        THEN 'em_cq'
        WHEN 'enviar_envase'    THEN 'envase'
        WHEN 'concluir_envase'  THEN 'pronto_entrega'
        WHEN 'gerar_estoque'    THEN 'pronto_entrega'
        WHEN 'reservar_estoque' THEN 'pronto_entrega'
        WHEN 'enviar_entrega'   THEN 'entregue'
        WHEN 'finalizar_os'     THEN 'finalizada'
        ELSE NULL
    END;

    EXECUTE format('SELECT status::text FROM %I WHERE id = $1 FOR UPDATE', v_tabela_os)
    INTO v_status_atual USING p_os_id;

    IF v_status_atual IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Ordem de serviço não encontrada.');
    END IF;

    -- IDEMPOTÊNCIA SERVER-SIDE (Gate 5): se a OS já está no status alvo da
    -- etapa, o replay é absorvido SEM novo evento de auditoria e SEM efeito.
    IF v_status_alvo IS NOT NULL AND v_status_atual = v_status_alvo THEN
        RETURN jsonb_build_object(
            'success', true,
            'replay', true,
            'message', 'Etapa já aplicada anteriormente.'
        );
    END IF;

    SELECT * INTO v_validacao FROM public.rpc_validar_integridade_esteira(p_os_id, p_origem_os, p_etapa_destino);
    IF NOT (v_validacao->>'permitido')::BOOLEAN THEN
        RETURN jsonb_build_object('success', false, 'message', (v_validacao->'bloqueios'->>0));
    END IF;

    v_etapa_anterior_os := v_status_atual;

    IF p_programacao_id IS NOT NULL AND p_programacao_id <> '00000000-0000-0000-0000-000000000000'::uuid THEN
        SELECT id INTO v_lote_id FROM public.lotes WHERE programacao_id = p_programacao_id FOR UPDATE;
    ELSE
        IF p_origem_os IN ('manual','b2b') THEN
            SELECT l.id INTO v_lote_id FROM public.lotes l JOIN public.programacao_producao pp ON l.programacao_id = pp.id WHERE pp.ordem_servico_id = p_os_id LIMIT 1;
        ELSE
            SELECT l.id INTO v_lote_id FROM public.lotes l JOIN public.programacao_producao pp ON l.programacao_id = pp.id WHERE pp.ordem_servico_onfarm_id = p_os_id LIMIT 1;
        END IF;
    END IF;

    CASE p_etapa_destino
        WHEN 'assumir_producao' THEN
            PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'em_producao');
            IF p_programacao_id IS NOT NULL THEN
                UPDATE public.programacao_producao SET status = 'em_producao', responsavel_id = v_profile_id WHERE id = p_programacao_id;
            END IF;
        WHEN 'gerar_lote' THEN NULL;
        WHEN 'enviar_cq' THEN
            PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'em_cq');
            UPDATE public.lotes SET status = 'aguardando_cq' WHERE id = v_lote_id;
        WHEN 'aprovar_cq', 'reprovar_cq' THEN
            IF v_lote_id IS NULL THEN
                RETURN jsonb_build_object('success', false, 'message', 'Nenhum lote localizado para registrar o CQ.');
            END IF;
            PERFORM pg_advisory_xact_lock(hashtext('cq_lote:' || v_lote_id::text));

            SELECT resultado::text INTO v_cq_atual
              FROM public.controle_qualidade
             WHERE lote_id = v_lote_id
             ORDER BY created_at DESC, seq DESC
             LIMIT 1;

            IF p_etapa_destino = 'aprovar_cq' THEN
                -- replay de CQ aprovado: nao duplica laudo NEM evento
                IF v_cq_atual IS NOT DISTINCT FROM 'aprovado' THEN
                    UPDATE public.lotes SET status = 'aprovado' WHERE id = v_lote_id;
                    RETURN jsonb_build_object('success', true, 'replay', true,
                        'message', 'CQ já registrado como aprovado.');
                END IF;
                UPDATE public.lotes SET status = 'aprovado' WHERE id = v_lote_id;
                INSERT INTO public.controle_qualidade (lote_id, resultado, responsavel_id)
                VALUES (v_lote_id, 'aprovado', v_profile_id);
            ELSE
                IF v_cq_atual IS NOT DISTINCT FROM 'reprovado' THEN
                    UPDATE public.lotes SET status = 'reprovado' WHERE id = v_lote_id;
                    RETURN jsonb_build_object('success', true, 'replay', true,
                        'message', 'CQ já registrado como reprovado.');
                END IF;
                UPDATE public.lotes SET status = 'reprovado' WHERE id = v_lote_id;
                INSERT INTO public.controle_qualidade (lote_id, resultado, responsavel_id)
                VALUES (v_lote_id, 'reprovado', v_profile_id);
            END IF;
        WHEN 'enviar_envase' THEN PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'envase');
        WHEN 'concluir_envase' THEN PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'pronto_entrega');
        WHEN 'gerar_estoque', 'reservar_estoque' THEN PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'pronto_entrega');
        -- GATE 4: criar_entrega NAO altera o status da OS para 'entregue'.
        WHEN 'criar_entrega' THEN NULL;
        WHEN 'enviar_entrega' THEN PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'entregue');
        WHEN 'finalizar_os' THEN PERFORM public._avancar_os_status(p_origem_os, p_os_id, 'finalizada');
        ELSE
    END CASE;

    INSERT INTO public.laboratorio_esteira_eventos (os_id, origem_os, programacao_id, etapa_anterior, etapa_nova, acao, usuario_id)
    VALUES (p_os_id, p_origem_os, p_programacao_id, v_etapa_anterior_os, p_etapa_destino, p_etapa_destino, auth.uid());

    RETURN jsonb_build_object('success', true, 'replay', false, 'message', 'Etapa avançada com sucesso');
END;
$function$

CREATE OR REPLACE FUNCTION public._sync_planning_from_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_order_id uuid;
  v_planning_id uuid;
  v_total int;
  v_done int;
  v_in_prod int;
BEGIN
  v_partner_order_id := COALESCE(NEW.partner_order_id, OLD.partner_order_id);
  IF v_partner_order_id IS NULL THEN RETURN NEW; END IF;

  SELECT id INTO v_planning_id FROM public.production_planning WHERE partner_order_id = v_partner_order_id;
  IF v_planning_id IS NULL THEN RETURN NEW; END IF;

  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE status IN ('finalizada','entregue','pronto_entrega')),
         COUNT(*) FILTER (WHERE status IN ('em_producao','em_cq','envase','programada'))
    INTO v_total, v_done, v_in_prod
  FROM public.ordens_servico WHERE partner_order_id = v_partner_order_id;

  IF v_total = 0 THEN RETURN NEW; END IF;

  IF v_done = v_total THEN
    UPDATE public.production_planning SET status='produzido', updated_at=now()
      WHERE id=v_planning_id AND status <> 'produzido';
  ELSIF v_in_prod > 0 THEN
    UPDATE public.production_planning SET status='em_producao', updated_at=now()
      WHERE id=v_planning_id AND status NOT IN ('em_producao','produzido','entregue');
  END IF;

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.audit_partner_order_payment_terms()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_id uuid;
BEGIN
  SELECT partner_id INTO v_partner_id FROM public.partner_orders WHERE id = NEW.partner_order_id;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.partner_order_audit_logs (order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
    VALUES (NEW.partner_order_id, v_partner_id, auth.uid(), 'payment_terms_created', NULL, to_jsonb(NEW));
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.partner_order_audit_logs (order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
    VALUES (NEW.partner_order_id, v_partner_id, auth.uid(), 'payment_terms_updated', to_jsonb(OLD), to_jsonb(NEW));
    RETURN NEW;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_advance_solicitacao_on_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_solicitacao_id uuid;
BEGIN
  IF NEW.registro_consultor_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT solicitacao_id INTO v_solicitacao_id
    FROM public.registros_consultor WHERE id = NEW.registro_consultor_id;
  IF v_solicitacao_id IS NOT NULL THEN
    UPDATE public.portal_solicitacoes
      SET status = 'aguardando_os', updated_at = now()
      WHERE id = v_solicitacao_id
        AND status NOT IN ('concluida','cancelada');
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.catalog_sources_set_source_key()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ref text;
BEGIN
  v_ref := coalesce(NEW.fonte_url, NEW.fonte_titulo, '');
  v_ref := regexp_replace(trim(lower(v_ref)), '\s+', ' ', 'g');
  NEW.source_key := lower(md5(
    trim(lower(coalesce(NEW.entidade_tipo, ''))) || ':' ||
    trim(lower(coalesce(NEW.entidade_id::text, ''))) || ':' ||
    v_ref
  ));
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_os_item_ref()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.produto_id IS NULL AND NEW.microrganismo_id IS NULL THEN
    RAISE EXCEPTION 'Ordem de Serviço precisa de produto_id OU microrganismo_id';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_os_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  status_order text[] := ARRAY['aberta', 'aprovada', 'programada', 'em_producao', 'em_cq', 'envase', 'aguardando_reserva', 'pronto_entrega', 'entregue', 'finalizada'];
  old_idx int;
  new_idx int;
  cq_count int;
  v_lote_id uuid;
BEGIN
  IF TG_TABLE_NAME='ordens_servico' AND OLD.status::text='programada' AND NEW.status::text='em_cq'
   AND EXISTS(SELECT 1 FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope='manual_cq_send_v1' AND target=NEW.id)
   AND EXISTS(SELECT 1 FROM public.programacao_producao p JOIN public.lotes l ON l.programacao_id=p.id JOIN public.clientes c ON c.id=NEW.cliente_id
    WHERE p.ordem_servico_id=NEW.id AND p.ordem_servico_onfarm_id IS NULL AND p.organization_id=platform_private.h15_actor_organization()
    AND l.organization_id=p.organization_id AND NEW.organization_id=p.organization_id AND c.organization_id=p.organization_id AND l.status::text='em_producao')
  THEN RETURN NEW; END IF;
  -- Se o status não mudou, permite
  IF (OLD.status::text = NEW.status::text) THEN
    RETURN NEW;
  END IF;

  -- Se o novo status é 'cancelada', permite
  IF (NEW.status::text = 'cancelada') THEN
    RETURN NEW;
  END IF;

  -- Validação específica: Bloquear avanço para 'envase' se o CQ não estiver aprovado
  IF (NEW.status::text = 'envase') THEN
    -- Encontrar o lote associado a esta OS OnFarm
    -- A relação é OS -> Programação -> Lote
    SELECT l.id INTO v_lote_id
    FROM public.lotes l
    JOIN public.programacao_producao pp ON l.programacao_id = pp.id
    WHERE pp.ordem_servico_onfarm_id = NEW.id
    LIMIT 1;

    -- Se não encontrar por ordem_servico_onfarm_id, tenta pelo ordem_servico_id (caso seja OS padrão)
    IF v_lote_id IS NULL THEN
        SELECT l.id INTO v_lote_id
        FROM public.lotes l
        JOIN public.programacao_producao pp ON l.programacao_id = pp.id
        WHERE pp.ordem_servico_id = NEW.id
        LIMIT 1;
    END IF;

    IF v_lote_id IS NOT NULL THEN
        -- Verificar se existe controle de qualidade aprovado para este lote
        -- Assumindo que o enum de resultado do CQ possui 'aprovado'
        SELECT count(*) INTO cq_count
        FROM public.controle_qualidade
        WHERE lote_id = v_lote_id AND resultado::text = 'aprovado';

        IF cq_count = 0 THEN
            RAISE EXCEPTION 'Não é possível avançar para ENVASE: O lote vinculado a esta Ordem de Serviço ainda não possui um laudo de Controle de Qualidade APROVADO.'
            USING ERRCODE = 'check_violation';
        END IF;
    ELSE
        -- Se não há lote/programação, mas tentou ir para envase, pode ser inconsistência de dados
        -- Mas se o fluxo operacional permite envase sem lote em casos raros, poderíamos ignorar.
        -- Para garantir segurança, vamos exigir o lote se estiver na fase de produção.
        RAISE EXCEPTION 'Não é possível avançar para ENVASE: Nenhum lote de produção foi localizado para esta Ordem de Serviço.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- Encontra os índices na esteira
  SELECT i INTO old_idx FROM unnest(status_order) WITH ORDINALITY AS t(val, i) WHERE val = OLD.status::text;
  SELECT i INTO new_idx FROM unnest(status_order) WITH ORDINALITY AS t(val, i) WHERE val = NEW.status::text;

  -- Validações:
  -- 1. Se o status antigo ou novo não estão na lista (e não é cancelamento), lança erro
  IF old_idx IS NULL OR new_idx IS NULL THEN
    RAISE EXCEPTION 'Status inválido ou transição não permitida para o fluxo operacional.';
  END IF;

  -- 2. Permite apenas avançar 1 posição por vez
  IF new_idx <> old_idx + 1
     AND NOT (new_idx = old_idx + 2 AND status_order[old_idx + 1] = 'aguardando_reserva') THEN
    RAISE EXCEPTION 'Transição de status inválida na esteira de produção: % -> %. A próxima etapa obrigatória é %.', 
      OLD.status::text, NEW.status::text, status_order[old_idx + 1];
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.comunicacao_templates_guard_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.status = 'active' THEN
    IF (NEW.corpo, NEW.assunto, NEW.variaveis, NEW.canal, NEW.chave, NEW.versao, NEW.locale)
       IS DISTINCT FROM
       (OLD.corpo, OLD.assunto, OLD.variaveis, OLD.canal, OLD.chave, OLD.versao, OLD.locale) THEN
      RAISE EXCEPTION 'template ativo imutável (chave=% canal=% versao=%)',
        OLD.chave, OLD.canal, OLD.versao USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status NOT IN ('active','archived') THEN
      RAISE EXCEPTION 'template ativo só transita para archived' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION public.enforce_cliente_id_for_produtor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid;
  v_role app_role;
  v_count int;
BEGIN
  -- Lógica específica para a tabela user_roles
  IF TG_TABLE_NAME = 'user_roles' THEN
    -- Aqui o record NEW possui o campo 'role'
    IF NEW.role = 'cliente_produtor' THEN
      SELECT count(*) INTO v_count
        FROM public.user_clientes WHERE user_id = NEW.user_id;
      IF v_count = 0 THEN
        RAISE EXCEPTION 'Para a função "Produtor (Portal)" é obrigatório vincular o usuário a pelo menos um cliente.'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  -- Lógica específica para a tabela user_clientes (que não possui campo 'role')
  IF TG_TABLE_NAME = 'user_clientes' THEN
    v_user := COALESCE(NEW.user_id, OLD.user_id);

    -- Verifica se o usuário tem a role de produtor
    SELECT role INTO v_role FROM public.user_roles
      WHERE user_id = v_user AND role = 'cliente_produtor' LIMIT 1;

    IF v_role IS NOT NULL THEN
      -- Conta quantos vínculos restariam após a operação
      IF TG_OP = 'DELETE' THEN
        SELECT count(*) INTO v_count FROM public.user_clientes
          WHERE user_id = v_user AND id <> OLD.id;
      ELSE
        SELECT count(*) INTO v_count FROM public.user_clientes
          WHERE user_id = v_user;
      END IF;

      IF v_count = 0 THEN
        RAISE EXCEPTION 'Este usuário é Produtor e precisa permanecer vinculado a pelo menos um cliente.'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    RETURN COALESCE(NEW, OLD);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;$function$

CREATE OR REPLACE FUNCTION public.fiscal_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid;
  v_allowed text[] := ARRAY[
    'company_fiscal_settings','product_fiscal_profiles','service_fiscal_profiles',
    'customer_fiscal_profiles','fiscal_invoices','fiscal_invoice_items',
    'fiscal_events','fiscal_idempotency_keys',
    'fiscal_operation_policies','fiscal_tax_rules','fiscal_document_series',
    'fiscal_number_reservations','fiscal_rule_sod_overrides','fiscal_calculation_runs'
  ];
BEGIN
  IF NOT (TG_TABLE_NAME = ANY(v_allowed)) THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  BEGIN v_actor := auth.uid(); EXCEPTION WHEN OTHERS THEN v_actor := NULL; END;
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, new_values)
    VALUES (TG_TABLE_NAME, NEW.id, 'INSERT', v_actor, public.mask_sensitive_jsonb(to_jsonb(NEW)));
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, old_values, new_values)
    VALUES (TG_TABLE_NAME, NEW.id, 'UPDATE', v_actor,
            public.mask_sensitive_jsonb(to_jsonb(OLD)), public.mask_sensitive_jsonb(to_jsonb(NEW)));
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, old_values)
    VALUES (TG_TABLE_NAME, OLD.id, 'DELETE', v_actor, public.mask_sensitive_jsonb(to_jsonb(OLD)));
    RETURN OLD;
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.fiscal_invoice_items_state_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_invoice_id uuid;
  v_status text;
begin
  v_invoice_id := case when tg_op = 'DELETE' then old.fiscal_invoice_id else new.fiscal_invoice_id end;
  if v_invoice_id is null then
    raise exception using errcode = 'P0001', message = 'O item fiscal deve estar vinculado a uma nota fiscal.';
  end if;

  select fi.normalized_status
    into v_status
    from public.fiscal_invoices fi
   where fi.id = v_invoice_id
   for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'A nota fiscal vinculada ao item não foi encontrada.';
  end if;

  if v_status is null or v_status not in ('DRAFT','VALIDATING','READY','REJECTED','ERROR') then
    raise exception using errcode = 'P0001', message = 'Os itens desta nota fiscal não podem ser alterados no estado atual.';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

