CREATE OR REPLACE FUNCTION public.fn_financial_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old jsonb; v_new jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'UPDATE' THEN v_old := to_jsonb(OLD); v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'DELETE' THEN v_old := to_jsonb(OLD);
  END IF;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, old_data, new_data, performed_by)
  VALUES (TG_TABLE_NAME, COALESCE((NEW).id, (OLD).id), TG_OP, v_old, v_new, auth.uid());

  RETURN COALESCE(NEW, OLD);
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_certificate_ref_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_certificate_id uuid;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.certificate_ref IS NOT DISTINCT FROM OLD.certificate_ref THEN
    RETURN NEW;
  END IF;

  IF NULLIF(BTRIM(NEW.certificate_ref), '') IS NULL THEN
    NEW.certificate_ref := NULL;
    RETURN NEW;
  END IF;

  IF NEW.certificate_ref !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    RAISE EXCEPTION 'certificate_ref_invalid' USING ERRCODE = '22023';
  END IF;

  v_certificate_id := NEW.certificate_ref::uuid;

  IF NOT EXISTS (
    SELECT 1
    FROM public.fiscal_certificates fc
    WHERE fc.id = v_certificate_id
      AND fc.company_settings_id = NEW.id
      AND fc.environment = 'HOMOLOGATION'
      AND fc.status = 'AVAILABLE'
      AND fc.is_active = true
      AND fc.valid_until > now()
  ) THEN
    RAISE EXCEPTION 'certificate_ref_not_active_homologation' USING ERRCODE = '22023';
  END IF;

  NEW.certificate_ref := v_certificate_id::text;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_cnpj_is_valid(_v text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  d text := public.fn_fiscal_digits(_v);
  w1 int[] := ARRAY[5,4,3,2,9,8,7,6,5,4,3,2];
  w2 int[] := ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2];
  s int := 0; i int; dv1 int; dv2 int;
BEGIN
  IF length(d) <> 14 THEN RETURN false; END IF;
  IF d ~ ('^(' || substr(d,1,1) || '){14}$') THEN RETURN false; END IF;
  FOR i IN 1..12 LOOP s := s + substr(d,i,1)::int * w1[i]; END LOOP;
  dv1 := s % 11; dv1 := CASE WHEN dv1 < 2 THEN 0 ELSE 11 - dv1 END;
  IF dv1 <> substr(d,13,1)::int THEN RETURN false; END IF;
  s := 0;
  FOR i IN 1..13 LOOP s := s + substr(d,i,1)::int * w2[i]; END LOOP;
  dv2 := s % 11; dv2 := CASE WHEN dv2 < 2 THEN 0 ELSE 11 - dv2 END;
  RETURN dv2 = substr(d,14,1)::int;
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_cpf_is_valid(_v text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  d text := public.fn_fiscal_digits(_v);
  s int := 0; i int; dv1 int; dv2 int;
BEGIN
  IF length(d) <> 11 THEN RETURN false; END IF;
  IF d ~ ('^(' || substr(d,1,1) || '){11}$') THEN RETURN false; END IF;
  FOR i IN 1..9 LOOP s := s + substr(d,i,1)::int * (11 - i); END LOOP;
  dv1 := (s * 10) % 11; IF dv1 = 10 THEN dv1 := 0; END IF;
  IF dv1 <> substr(d,10,1)::int THEN RETURN false; END IF;
  s := 0;
  FOR i IN 1..10 LOOP s := s + substr(d,i,1)::int * (12 - i); END LOOP;
  dv2 := (s * 10) % 11; IF dv2 = 10 THEN dv2 := 0; END IF;
  RETURN dv2 = substr(d,11,1)::int;
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_emitter_pendencies_row(r company_fiscal_settings)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE out jsonb := '[]'::jsonb; ie_state text;
BEGIN
  IF current_setting('role', true) = 'service_role' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.organizations o
      WHERE o.id = r.organization_id AND o.ativo IS TRUE
    ) THEN
      RAISE EXCEPTION 'H15_ORGANIZATION_FORBIDDEN' USING ERRCODE='42501';
    END IF;
  ELSE
    PERFORM public.h15_require_staff();
    IF r.organization_id IS DISTINCT FROM public.h15_actor_organization() THEN
      RAISE EXCEPTION 'H15_COMPANY_FORBIDDEN' USING ERRCODE='42501';
    END IF;
  END IF;

  IF NOT public.fn_fiscal_cnpj_is_valid(r.cnpj) THEN
    out := out || jsonb_build_object('code','EMITTER_CNPJ_INVALID','field','cnpj','severity','BLOCK','message','CNPJ ausente ou com digito verificador invalido.');
  END IF;
  IF nullif(btrim(coalesce(r.legal_name,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_LEGAL_NAME_MISSING','field','legal_name','severity','BLOCK','message','Razao social obrigatoria.');
  END IF;
  IF r.crt IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_CRT_MISSING','field','crt','severity','BLOCK','message','CRT (1,2,3,4) obrigatorio.');
  END IF;
  IF nullif(btrim(coalesce(r.primary_cnae,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_CNAE_MISSING','field','primary_cnae','severity','BLOCK','message','CNAE principal obrigatorio.');
  END IF;
  IF r.pis_cofins_regime IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_PIS_COFINS_REGIME_MISSING','field','pis_cofins_regime','severity','BLOCK','message','Regime de PIS/COFINS obrigatorio para calculo.');
  END IF;
  IF NOT public.fn_fiscal_cep_is_valid(r.postal_code) THEN
    out := out || jsonb_build_object('code','EMITTER_CEP_INVALID','field','postal_code','severity','BLOCK','message','CEP deve ter 8 digitos.');
  END IF;
  IF public.fn_fiscal_uf_ibge_code(r.state) IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_UF_INVALID','field','state','severity','BLOCK','message','UF invalida.');
  ELSIF NOT public.fn_fiscal_ibge_municipio_coerente(r.municipality_ibge_code, r.state) THEN
    out := out || jsonb_build_object('code','EMITTER_IBGE_INCOHERENT','field','municipality_ibge_code','severity','BLOCK','message','Codigo IBGE do municipio ausente ou incoerente com a UF.');
  END IF;
  IF nullif(btrim(coalesce(r.street,'')),'') IS NULL
     OR nullif(btrim(coalesce(r.number,'')),'') IS NULL
     OR nullif(btrim(coalesce(r.neighborhood,'')),'') IS NULL
     OR nullif(btrim(coalesce(r.city,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_ADDRESS_INCOMPLETE','field','address','severity','BLOCK','message','Endereco completo obrigatorio (logradouro, numero, bairro, municipio).');
  END IF;
  IF coalesce(r.country_code,'') NOT IN ('1058','BR') THEN
    out := out || jsonb_build_object('code','EMITTER_COUNTRY_MISSING','field','country_code','severity','BLOCK','message','Pais obrigatorio (1058 - Brasil).');
  END IF;
  ie_state := public.fn_fiscal_ie_check(r.state, r.state_registration);
  IF ie_state IN ('MISSING','INVALID_LENGTH','INVALID_DV','INVALID_FORMAT','INVALID_UF') THEN
    out := out || jsonb_build_object('code','EMITTER_IE_INVALID','field','state_registration','severity','BLOCK','message','Inscricao estadual invalida para a UF: '||ie_state);
  ELSIF ie_state = 'VALID_LENGTH_DV_NOT_IMPLEMENTED' THEN
    out := out || jsonb_build_object('code','EMITTER_IE_DV_NOT_IMPLEMENTED','field','state_registration','severity','WARN','message','IE com formato compativel; digito verificador desta UF nao e verificado automaticamente.');
  END IF;
  IF r.nfe_series_number IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_SERIES_MISSING','field','nfe_series_number','severity','BLOCK','message','Serie da NF-e (1-999) obrigatoria.');
  END IF;
  IF r.nfe_environment_code IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_ENVIRONMENT_MISSING','field','nfe_environment_code','severity','BLOCK','message','Ambiente tpAmb (2 homologacao / 1 producao) obrigatorio.');
  END IF;
  IF jsonb_array_length(r.uf_accreditations) = 0 THEN
    out := out || jsonb_build_object('code','EMITTER_ACCREDITATION_MISSING','field','uf_accreditations','severity','BLOCK','message','Credenciamento por UF nao registrado.');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.fiscal_certificates c
    WHERE c.id::text = r.certificate_ref AND c.company_settings_id = r.id
      AND c.environment = 'HOMOLOGATION' AND c.status = 'AVAILABLE'
      AND c.is_active IS TRUE AND c.revoked_at IS NULL
      AND c.valid_from <= now() AND c.valid_until > now()) THEN
    out := out || jsonb_build_object('code','EMITTER_CERTIFICATE_MISSING','field','certificate_ref','severity','BLOCK','message','Certificado ausente, indisponivel, revogado, vencido ou de outra empresa.');
  END IF;
  IF r.accounting_validated_at IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_ACCOUNTING_NOT_VALIDATED','field','accounting_validated_at','severity','BLOCK','message','Validacao contabil pendente.');
  END IF;
  IF coalesce(r.nfe_environment_code,'2') = '1' THEN
    out := out || jsonb_build_object('code','EMITTER_PRODUCTION_BLOCKED_F3','field','nfe_environment_code','severity','BLOCK',
      'message','Ambiente de producao (tpAmb=1) bloqueado na fase F3: teto e READY_HOMOLOGATION ate fluxo controlado de homologacao SEFAZ.');
  END IF;
  RETURN out;
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_ie_check(_uf text, _ie text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  uf text := upper(btrim(coalesce(_uf,'')));
  raw text := upper(btrim(coalesce(_ie,'')));
  d text; len int; s int := 0; i int; dv int; w int;
BEGIN
  IF raw = '' THEN RETURN 'MISSING'; END IF;
  IF raw IN ('ISENTO','ISENTA') THEN RETURN 'ISENTO'; END IF;
  IF public.fn_fiscal_uf_ibge_code(uf) IS NULL THEN RETURN 'INVALID_UF'; END IF;
  d := public.fn_fiscal_digits(raw);
  len := length(d);

  IF (uf = 'AC' AND len <> 13)
  OR (uf = 'AL' AND len <> 9) OR (uf = 'AM' AND len <> 9)
  OR (uf = 'AP' AND len <> 9) OR (uf = 'BA' AND len NOT IN (8,9))
  OR (uf = 'CE' AND len <> 9) OR (uf = 'DF' AND len <> 13)
  OR (uf = 'ES' AND len <> 9) OR (uf = 'GO' AND len <> 9)
  OR (uf = 'MA' AND len <> 9) OR (uf = 'MG' AND len <> 13)
  OR (uf = 'MS' AND len <> 9) OR (uf = 'MT' AND len <> 11)
  OR (uf = 'PA' AND len <> 9) OR (uf = 'PB' AND len <> 9)
  OR (uf = 'PE' AND len NOT IN (9,14)) OR (uf = 'PI' AND len <> 9)
  OR (uf = 'PR' AND len <> 10) OR (uf = 'RJ' AND len <> 8)
  OR (uf = 'RN' AND len NOT IN (9,10)) OR (uf = 'RO' AND len <> 14)
  OR (uf = 'RR' AND len <> 9) OR (uf = 'RS' AND len <> 10)
  OR (uf = 'SC' AND len <> 9) OR (uf = 'SE' AND len <> 9)
  OR (uf = 'SP' AND len NOT IN (12,13)) OR (uf = 'TO' AND len <> 9)
  THEN
    RETURN 'INVALID_LENGTH';
  END IF;

  -- Dígito verificador: subconjunto com algoritmo público e estável.
  IF uf = 'GO' THEN
    IF substr(d,1,2) NOT IN ('10','11','15') THEN RETURN 'INVALID_FORMAT'; END IF;
    s := 0;
    FOR i IN 1..8 LOOP s := s + substr(d,i,1)::int * (10 - i); END LOOP;
    dv := s % 11;
    dv := CASE WHEN dv = 0 THEN 0 WHEN dv = 1 THEN 1 ELSE 11 - dv END;
    RETURN CASE WHEN dv = substr(d,9,1)::int THEN 'VALID_DV' ELSE 'INVALID_DV' END;
  ELSIF uf = 'RJ' THEN
    s := 0; w := 2;
    FOR i IN 1..7 LOOP
      s := s + substr(d,i,1)::int * w;
      w := CASE WHEN w = 7 THEN 2 ELSE w + 1 END;
    END LOOP;
    dv := 11 - (s % 11); IF dv >= 10 THEN dv := 0; END IF;
    RETURN CASE WHEN dv = substr(d,8,1)::int THEN 'VALID_DV' ELSE 'INVALID_DV' END;
  ELSIF uf = 'SC' THEN
    s := 0;
    FOR i IN 1..8 LOOP s := s + substr(d,i,1)::int * (10 - i); END LOOP;
    dv := 11 - (s % 11); IF dv >= 10 THEN dv := 0; END IF;
    RETURN CASE WHEN dv = substr(d,9,1)::int THEN 'VALID_DV' ELSE 'INVALID_DV' END;
  END IF;

  RETURN 'VALID_LENGTH_DV_NOT_IMPLEMENTED';
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_recipient_pendencies_row(r customer_fiscal_profiles)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE out jsonb := '[]'::jsonb; ie_state text; doc text;
BEGIN
  doc := public.fn_fiscal_digits(r.cpf_cnpj);
  IF r.person_type IS NULL THEN
    out := out || jsonb_build_object('code','RECIPIENT_PERSON_TYPE_MISSING','field','person_type','severity','BLOCK','message','Tipo de pessoa (PF/PJ/ESTRANGEIRO) obrigatorio.');
  ELSIF r.person_type = 'PJ' AND NOT public.fn_fiscal_cnpj_is_valid(doc) THEN
    out := out || jsonb_build_object('code','RECIPIENT_CNPJ_INVALID','field','cpf_cnpj','severity','BLOCK','message','CNPJ do destinatario invalido.');
  ELSIF r.person_type = 'PF' AND NOT public.fn_fiscal_cpf_is_valid(doc) THEN
    out := out || jsonb_build_object('code','RECIPIENT_CPF_INVALID','field','cpf_cnpj','severity','BLOCK','message','CPF do destinatario invalido.');
  ELSIF r.person_type = 'ESTRANGEIRO' AND coalesce(r.country_code,'1058') IN ('1058','BR') THEN
    out := out || jsonb_build_object('code','RECIPIENT_FOREIGN_COUNTRY_REQUIRED','field','country_code','severity','BLOCK','message','Destinatario estrangeiro exige pais diferente de Brasil.');
  END IF;

  IF nullif(btrim(coalesce(r.legal_name,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','RECIPIENT_NAME_MISSING','field','legal_name','severity','BLOCK','message','Razao social / nome do destinatario obrigatorio.');
  END IF;
  IF r.taxpayer_indicator IS NULL THEN
    out := out || jsonb_build_object('code','RECIPIENT_TAXPAYER_INDICATOR_MISSING','field','taxpayer_indicator','severity','BLOCK','message','Indicador de IE do destinatario (indIEDest) obrigatorio.');
  END IF;
  IF coalesce(r.foreign_customer_indicator,false) = false THEN
    IF public.fn_fiscal_uf_ibge_code(r.fiscal_state) IS NULL THEN
      out := out || jsonb_build_object('code','RECIPIENT_UF_INVALID','field','fiscal_state','severity','BLOCK','message','UF do destinatario invalida.');
    ELSIF NOT public.fn_fiscal_ibge_municipio_coerente(r.fiscal_municipality_ibge_code, r.fiscal_state) THEN
      out := out || jsonb_build_object('code','RECIPIENT_IBGE_INCOHERENT','field','fiscal_municipality_ibge_code','severity','BLOCK','message','Codigo IBGE do municipio ausente ou incoerente com a UF.');
    END IF;
    IF NOT public.fn_fiscal_cep_is_valid(r.fiscal_postal_code) THEN
      out := out || jsonb_build_object('code','RECIPIENT_CEP_INVALID','field','fiscal_postal_code','severity','BLOCK','message','CEP do destinatario deve ter 8 digitos.');
    END IF;
    IF nullif(btrim(coalesce(r.fiscal_street,'')),'') IS NULL
       OR nullif(btrim(coalesce(r.fiscal_number,'')),'') IS NULL
       OR nullif(btrim(coalesce(r.fiscal_neighborhood,'')),'') IS NULL
       OR nullif(btrim(coalesce(r.fiscal_city,'')),'') IS NULL THEN
      out := out || jsonb_build_object('code','RECIPIENT_ADDRESS_INCOMPLETE','field','address','severity','BLOCK','message','Endereco fiscal completo obrigatorio.');
    END IF;
    IF coalesce(r.icms_taxpayer,false) THEN
      ie_state := public.fn_fiscal_ie_check(r.fiscal_state, r.state_registration);
      IF ie_state IN ('MISSING','INVALID_LENGTH','INVALID_DV','INVALID_FORMAT','INVALID_UF','ISENTO') THEN
        out := out || jsonb_build_object('code','RECIPIENT_IE_INVALID','field','state_registration','severity','BLOCK','message','Destinatario contribuinte exige IE valida: '||ie_state);
      ELSIF ie_state = 'VALID_LENGTH_DV_NOT_IMPLEMENTED' THEN
        out := out || jsonb_build_object('code','RECIPIENT_IE_DV_NOT_IMPLEMENTED','field','state_registration','severity','WARN','message','IE com formato compativel; DV desta UF nao e verificado automaticamente.');
      END IF;
    END IF;
  END IF;
  IF nullif(btrim(coalesce(r.fiscal_email,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','RECIPIENT_FISCAL_EMAIL_MISSING','field','fiscal_email','severity','WARN','message','E-mail fiscal ausente; DANFE/XML nao poderao ser enviados automaticamente.');
  END IF;
  RETURN out;
END $function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_sefaz_tx_link_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_run_invoice   uuid;
  v_run_state     text;
  v_event_invoice uuid;
  v_event_state   text;
BEGIN
  -- H7G-001: autorização sempre amarrada ao invoice do próprio XML run.
  IF NEW.service = 'NFeAutorizacao4' THEN
    IF NEW.xml_run_id IS NULL THEN
      RAISE EXCEPTION 'SEFAZ_RUN_REQUIRED';
    END IF;
    SELECT fiscal_invoice_id, state INTO v_run_invoice, v_run_state
      FROM public.fiscal_xml_runs WHERE id = NEW.xml_run_id;
    IF v_run_invoice IS NULL THEN
      RAISE EXCEPTION 'SEFAZ_RUN_NOT_FOUND';
    END IF;
    IF v_run_state IS DISTINCT FROM 'SIGNED' THEN
      RAISE EXCEPTION 'SEFAZ_DOCUMENT_NOT_SIGNED';
    END IF;
    IF NEW.fiscal_invoice_id IS DISTINCT FROM v_run_invoice THEN
      RAISE EXCEPTION 'SEFAZ_INVOICE_RUN_MISMATCH';
    END IF;
  END IF;

  IF NEW.xml_run_id IS NOT NULL AND NEW.service <> 'NFeAutorizacao4' THEN
    SELECT fiscal_invoice_id INTO v_run_invoice
      FROM public.fiscal_xml_runs WHERE id = NEW.xml_run_id;
    IF NEW.fiscal_invoice_id IS DISTINCT FROM v_run_invoice THEN
      RAISE EXCEPTION 'SEFAZ_INVOICE_RUN_MISMATCH';
    END IF;
  END IF;

  -- H7G-002: evento sempre amarrado a um evento fiscal preparado e assinado.
  IF NEW.service = 'NFeRecepcaoEvento4' THEN
    IF NEW.fiscal_event_id IS NULL THEN
      RAISE EXCEPTION 'SEFAZ_EVENT_REQUIRED';
    END IF;
    SELECT fiscal_invoice_id, state INTO v_event_invoice, v_event_state
      FROM public.v_fiscal_sefaz_event_state WHERE event_id = NEW.fiscal_event_id;
    IF v_event_invoice IS NULL THEN
      RAISE EXCEPTION 'SEFAZ_EVENT_NOT_FOUND';
    END IF;
    IF v_event_state NOT IN ('SIGNED','REJECTED') THEN
      RAISE EXCEPTION 'SEFAZ_EVENT_NOT_SIGNED';
    END IF;
    IF NEW.fiscal_invoice_id IS DISTINCT FROM v_event_invoice THEN
      RAISE EXCEPTION 'SEFAZ_EVENT_INVOICE_MISMATCH';
    END IF;
  ELSIF NEW.fiscal_event_id IS NOT NULL THEN
    RAISE EXCEPTION 'SEFAZ_EVENT_SERVICE_MISMATCH';
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_generate_payable_installments()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  i int;
  v_context platform_private.financial_initial_installments;
  v_inst jsonb;
  v_qtd int := NEW.installment_count;
  v_base numeric(14,2) := ROUND(NEW.total_amount / v_qtd, 2);
  v_acc numeric(14,2) := 0;
  v_amt numeric(14,2);
BEGIN
  IF NEW.organization_id IS NULL THEN
    RAISE EXCEPTION 'FINANCIAL_TENANT_REQUIRED' USING ERRCODE='23514';
  END IF;
  DELETE FROM platform_private.financial_initial_installments
    WHERE transaction_id=txid_current() AND title_id=NEW.id AND kind='payable'
    RETURNING * INTO v_context;
  IF FOUND THEN
    IF v_context.actor_id IS DISTINCT FROM auth.uid() OR v_context.organization_id IS DISTINCT FROM NEW.organization_id
       OR NEW.created_by IS DISTINCT FROM v_context.actor_id OR NEW.origin_type <> 'MANUAL'
       OR platform_private.h15_actor_organization() IS DISTINCT FROM NEW.organization_id
       OR NOT public.is_financial_staff(auth.uid()) THEN
      RAISE EXCEPTION 'FIN_INITIAL_CONTEXT_DENIED' USING ERRCODE='42501';
    END IF;
    IF jsonb_array_length(v_context.installments) <> NEW.installment_count
       OR (SELECT sum((x->>'amount')::numeric) FROM jsonb_array_elements(v_context.installments) x) IS DISTINCT FROM NEW.total_amount THEN
      RAISE EXCEPTION 'FIN_TITLE_INVALID_SUM' USING ERRCODE='23514';
    END IF;
    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_context.installments) LOOP
      INSERT INTO public.accounts_payable_installments(organization_id,payable_id,installment_number,due_date,original_amount,net_amount,status)
        VALUES(NEW.organization_id,NEW.id,(v_inst->>'installment_number')::int,(v_inst->>'due_date')::date,
          (v_inst->>'amount')::numeric,(v_inst->>'amount')::numeric,'OPEN');
    END LOOP;
    RETURN NEW;
  END IF;
  FOR i IN 1..v_qtd LOOP
    IF i < v_qtd THEN
      v_amt := v_base;
      v_acc := v_acc + v_amt;
    ELSE
      v_amt := NEW.total_amount - v_acc;
    END IF;
    INSERT INTO public.accounts_payable_installments
      (organization_id, payable_id, installment_number, due_date, original_amount, net_amount, status)
    VALUES
      (NEW.organization_id, NEW.id, i, (NEW.first_due_date + ((i-1) || ' months')::interval)::date, v_amt, v_amt, 'OPEN');
  END LOOP;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_generate_receivable_from_entrega(_entrega_id uuid, _payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_entrega public.entregas%ROWTYPE;
  v_receivable_id uuid;
  v_total numeric(14,2);
  v_canon jsonb;
  v_canon_valor numeric;
  v_canon_origem text;
  v_manual boolean;
  v_manual_reason text;
  v_count integer;
  v_category uuid; v_cost_center uuid; v_payment_method uuid;
  v_first_due date; v_issue date;
  v_fiscal_required boolean; v_fiscal_status text;
  v_installments jsonb; v_sum numeric(14,2) := 0; v_inst jsonb;
  v_desc text; v_notes text; v_guard jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão inválida.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NOT public.is_financial_staff(v_uid) THEN
    RAISE EXCEPTION 'Sem permissão para faturar entregas.' USING ERRCODE='insufficient_privilege';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('entrega_faturar:' || _entrega_id::text, 0));

  SELECT * INTO v_entrega FROM public.entregas WHERE id = _entrega_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrega não encontrada.'; END IF;

  -- H6-003.5 replay estavel
  IF v_entrega.receivable_id IS NOT NULL THEN
    RETURN v_entrega.receivable_id;
  END IF;

  IF v_entrega.status = 'cancelada' THEN
    RAISE EXCEPTION 'Entrega cancelada não pode ser faturada.' USING ERRCODE='check_violation';
  END IF;
  IF v_entrega.status <> 'entregue' THEN
    RAISE EXCEPTION 'Entrega precisa estar com status "entregue" para faturar.' USING ERRCODE='check_violation';
  END IF;
  IF v_entrega.cliente_id IS NULL THEN
    RAISE EXCEPTION 'Entrega sem cliente vinculado.' USING ERRCODE='check_violation';
  END IF;
  IF v_entrega.financial_status = 'NOT_BILLABLE' THEN
    RAISE EXCEPTION 'Entrega marcada como não faturável.' USING ERRCODE='check_violation';
  END IF;

  v_total           := COALESCE((_payload->>'total_amount')::numeric, 0);
  v_count           := COALESCE((_payload->>'installment_count')::integer, 1);
  v_category        := NULLIF(_payload->>'category_id','')::uuid;
  v_cost_center     := NULLIF(_payload->>'cost_center_id','')::uuid;
  v_payment_method  := NULLIF(_payload->>'payment_method_id','')::uuid;
  v_first_due       := COALESCE((_payload->>'first_due_date')::date, CURRENT_DATE);
  v_issue           := COALESCE((_payload->>'issue_date')::date, CURRENT_DATE);
  v_fiscal_required := COALESCE((_payload->>'fiscal_invoice_required')::boolean, false);
  v_fiscal_status   := CASE WHEN v_fiscal_required THEN 'PENDING' ELSE 'NOT_REQUIRED' END;
  v_installments    := _payload->'installments';
  v_desc            := COALESCE(NULLIF(_payload->>'description',''), 'Entrega ' || substr(_entrega_id::text,1,8));
  v_notes           := NULLIF(_payload->>'notes','');
  v_manual          := COALESCE((_payload->>'manual_financial_adjustment')::boolean, false);
  v_manual_reason   := NULLIF(trim(_payload->>'manual_adjustment_reason'), '');

  IF v_category IS NULL THEN
    RAISE EXCEPTION 'Categoria financeira é obrigatória.' USING ERRCODE='check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.financial_categories WHERE id = v_category) THEN
    RAISE EXCEPTION 'Categoria financeira não encontrada.' USING ERRCODE='check_violation';
  END IF;
  IF v_count < 1 OR v_count > 36 THEN
    RAISE EXCEPTION 'Número de parcelas deve estar entre 1 e 36.' USING ERRCODE='check_violation';
  END IF;

  -- ------- H6-003: valor canonico server-side é a autoridade do total -------
  v_canon := public.fn_entrega_valor_faturavel_v1(_entrega_id);
  v_canon_origem := v_canon->>'origem';

  -- reconciliacao parcial: usa exatamente o valor_faturavel_max persistido
  SELECT r.valor_faturavel_max INTO v_canon_valor
    FROM public.entrega_reconciliacoes r
   WHERE r.entrega_id = _entrega_id AND r.status = 'reconciliada'
   LIMIT 1;
  IF v_canon_valor IS NULL THEN
    v_canon_valor := (v_canon->>'valor')::numeric;
  ELSE
    v_canon_origem := 'RECONCILIACAO:' || COALESCE(v_canon_origem,'-');
  END IF;

  IF v_canon_valor IS NOT NULL THEN
    IF abs(v_total - v_canon_valor) > 0.01 THEN
      RAISE EXCEPTION 'valor_divergente_do_canonico: informado %, canônico % (origem %).',
        v_total, v_canon_valor, v_canon_origem USING ERRCODE='check_violation';
    END IF;
    v_total := round(v_canon_valor, 2);
  ELSE
    -- sem fonte historica confiavel: exige ajuste financeiro manual justificado
    IF NOT v_manual OR v_manual_reason IS NULL OR length(v_manual_reason) < 10 THEN
      RAISE EXCEPTION 'valor_canonico_indisponivel: informe manual_financial_adjustment com motivo (mín. 10 caracteres).'
        USING ERRCODE='check_violation';
    END IF;
  END IF;

  IF v_total <= 0 THEN
    RAISE EXCEPTION 'Valor total inválido.' USING ERRCODE='check_violation';
  END IF;

  -- GATE: reconciliação obrigatória quando há conferência por item
  v_guard := public.fn_entrega_guard_faturamento_v1(_entrega_id, v_total);

  IF v_installments IS NOT NULL AND jsonb_array_length(v_installments) > 0 THEN
    IF jsonb_array_length(v_installments) <> v_count THEN
      RAISE EXCEPTION 'Quantidade de parcelas (%) diverge de installment_count (%).',
        jsonb_array_length(v_installments), v_count USING ERRCODE='check_violation';
    END IF;
    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_installments) LOOP
      v_sum := v_sum + COALESCE((v_inst->>'amount')::numeric, 0);
    END LOOP;
    IF abs(v_sum - v_total) > 0.01 THEN
      RAISE EXCEPTION 'Soma das parcelas (%) difere do total (%).', v_sum, v_total USING ERRCODE='check_violation';
    END IF;
  END IF;

  BEGIN
    INSERT INTO public.accounts_receivable (
      origin_type, origin_id, customer_id, description, category_id, cost_center_id,
      total_amount, issue_date, first_due_date, installment_count,
      payment_method_id, fiscal_invoice_required, fiscal_invoice_status,
      notes, created_by
    ) VALUES (
      'DELIVERY', _entrega_id, v_entrega.cliente_id, v_desc, v_category, v_cost_center,
      v_total, v_issue, v_first_due, v_count,
      v_payment_method, v_fiscal_required, v_fiscal_status,
      v_notes, v_uid
    ) RETURNING id INTO v_receivable_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT id INTO v_receivable_id FROM public.accounts_receivable
     WHERE origin_type = 'DELIVERY' AND origin_id = _entrega_id AND status <> 'CANCELED';
    IF v_receivable_id IS NOT NULL THEN RETURN v_receivable_id; END IF;
    RAISE EXCEPTION 'Entrega já possui conta a receber ativa.' USING ERRCODE='check_violation';
  END;

  IF v_installments IS NOT NULL AND jsonb_array_length(v_installments) > 0 THEN
    DELETE FROM public.accounts_receivable_installments WHERE receivable_id = v_receivable_id;
    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_installments) LOOP
      INSERT INTO public.accounts_receivable_installments (
        receivable_id, installment_number, due_date, original_amount, net_amount, status
      ) VALUES (
        v_receivable_id,
        (v_inst->>'installment_number')::integer,
        (v_inst->>'due_date')::date,
        (v_inst->>'amount')::numeric,
        (v_inst->>'amount')::numeric,
        'OPEN'
      );
    END LOOP;
  END IF;

  UPDATE public.entregas
     SET receivable_id = v_receivable_id,
         financial_status = 'BILLED',
         billing_generated_at = now(),
         billing_generated_by = v_uid
   WHERE id = _entrega_id;

  INSERT INTO public.financial_audit_log (
    entity_type, entity_id, action, old_data, new_data, performed_by
  ) VALUES (
    'entregas', _entrega_id, 'DELIVERY_BILLED',
    jsonb_build_object('receivable_id', v_entrega.receivable_id,
                       'financial_status', v_entrega.financial_status),
    jsonb_build_object('receivable_id', v_receivable_id, 'total_amount', v_total,
      'installment_count', v_count, 'fiscal_invoice_required', v_fiscal_required,
      'payment_method_id', v_payment_method, 'origem', 'entrega',
      'valor_canonico', v_canon_valor, 'valor_canonico_origem', v_canon_origem,
      'manual_financial_adjustment', v_manual, 'manual_adjustment_reason', v_manual_reason,
      'reconciliacao', v_guard),
    v_uid
  );

  RETURN v_receivable_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_generate_receivable_installments()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  i int;
  v_context platform_private.financial_initial_installments;
  v_inst jsonb;
  v_qtd int := NEW.installment_count;
  v_base numeric(14,2) := ROUND(NEW.total_amount / v_qtd, 2);
  v_acc numeric(14,2) := 0;
  v_amt numeric(14,2);
BEGIN
  IF NEW.organization_id IS NULL THEN
    RAISE EXCEPTION 'FINANCIAL_TENANT_REQUIRED' USING ERRCODE = '23514';
  END IF;
  DELETE FROM platform_private.financial_initial_installments
    WHERE transaction_id=txid_current() AND title_id=NEW.id AND kind='receivable'
    RETURNING * INTO v_context;
  IF FOUND THEN
    IF v_context.actor_id IS DISTINCT FROM auth.uid() OR v_context.organization_id IS DISTINCT FROM NEW.organization_id
       OR NEW.created_by IS DISTINCT FROM v_context.actor_id OR NEW.origin_type <> 'MANUAL'
       OR platform_private.h15_actor_organization() IS DISTINCT FROM NEW.organization_id
       OR NOT public.is_financial_staff(auth.uid()) THEN
      RAISE EXCEPTION 'FIN_INITIAL_CONTEXT_DENIED' USING ERRCODE='42501';
    END IF;
    IF jsonb_array_length(v_context.installments) <> NEW.installment_count
       OR (SELECT sum((x->>'amount')::numeric) FROM jsonb_array_elements(v_context.installments) x) IS DISTINCT FROM NEW.total_amount THEN
      RAISE EXCEPTION 'FIN_TITLE_INVALID_SUM' USING ERRCODE='23514';
    END IF;
    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_context.installments) LOOP
      INSERT INTO public.accounts_receivable_installments(organization_id,receivable_id,installment_number,due_date,original_amount,net_amount,status)
        VALUES(NEW.organization_id,NEW.id,(v_inst->>'installment_number')::int,(v_inst->>'due_date')::date,
          (v_inst->>'amount')::numeric,(v_inst->>'amount')::numeric,'OPEN');
    END LOOP;
    RETURN NEW;
  END IF;
  IF NEW.origin_type='B2B_ORDER' AND EXISTS(SELECT 1 FROM public.partner_orders o WHERE o.id=NEW.origin_id AND o.c2_external_origin_snapshot IS NOT NULL) THEN
    INSERT INTO public.accounts_receivable_installments(receivable_id,installment_number,due_date,original_amount,net_amount,status,organization_id,interest_amount)
    SELECT NEW.id,s.installment_number,s.due_date,s.amount,s.amount,'OPEN',NEW.organization_id,s.interest_amount
    FROM public.partner_order_payment_schedule s JOIN public.partner_orders o ON o.id=s.partner_order_id AND o.payment_terms_id=s.payment_terms_id
    WHERE o.id=NEW.origin_id ORDER BY s.installment_number;
    IF (SELECT count(*) FROM public.accounts_receivable_installments WHERE receivable_id=NEW.id)<>v_qtd THEN RAISE EXCEPTION 'B2B_INSTALLMENT_CARDINALITY_INVALID' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  FOR i IN 1..v_qtd LOOP
    IF i < v_qtd THEN
      v_amt := v_base;
      v_acc := v_acc + v_amt;
    ELSE
      v_amt := NEW.total_amount - v_acc;
    END IF;
    INSERT INTO public.accounts_receivable_installments
      (receivable_id, installment_number, due_date, original_amount, net_amount, status, organization_id)
    VALUES
      (NEW.id, i, (NEW.first_due_date + ((i-1) || ' months')::interval)::date, v_amt, v_amt, 'OPEN', NEW.organization_id);
  END LOOP;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.fn_generate_recurring_title(_template_id uuid, _reference_date date, _is_manual boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t public.recurring_financial_templates%ROWTYPE;
  v_new_id UUID;
  v_user UUID;
BEGIN
  -- H7O: sessão interna/cron (sem JWT) preservada; chamada autenticada exige staff financeiro.
  IF auth.uid() IS NOT NULL AND NOT public.is_financial_staff(auth.uid()) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501',
      HINT = 'H7O: geração de título recorrente restrita ao staff financeiro.';
  END IF;

  SELECT * INTO t FROM public.recurring_financial_templates
  WHERE id = _template_id AND organization_id IS NOT NULL
    AND (auth.uid() IS NULL OR organization_id = platform_private.h15_actor_organization())
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Template não encontrado'; END IF;

  IF NOT t.active THEN
    INSERT INTO public.recurring_generation_log(template_id, reference_date, status, error_message, generated_by, generated_entity_type, amount)
    VALUES (_template_id, _reference_date, 'SKIPPED', 'Template inativo', auth.uid(), t.type, t.amount);
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by, reason)
    VALUES ('RECURRING_TEMPLATE', _template_id, 'RECURRING_GENERATION_SKIPPED', jsonb_build_object('reference_date', _reference_date), auth.uid(), 'Template inativo');
    RETURN NULL;
  END IF;

  IF t.end_date IS NOT NULL AND _reference_date > t.end_date THEN
    INSERT INTO public.recurring_generation_log(template_id, reference_date, status, error_message, generated_by, generated_entity_type, amount)
    VALUES (_template_id, _reference_date, 'SKIPPED', 'Após data final', auth.uid(), t.type, t.amount);
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by, reason)
    VALUES ('RECURRING_TEMPLATE', _template_id, 'RECURRING_GENERATION_SKIPPED', jsonb_build_object('reference_date', _reference_date), auth.uid(), 'Após data final');
    RETURN NULL;
  END IF;

  IF EXISTS (SELECT 1 FROM public.recurring_generation_log WHERE template_id = _template_id AND reference_date = _reference_date AND status = 'SUCCESS') THEN
    INSERT INTO public.recurring_generation_log(template_id, reference_date, status, error_message, generated_by, generated_entity_type, amount)
    VALUES (_template_id, _reference_date, 'SKIPPED', 'Competência já gerada', auth.uid(), t.type, t.amount);
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by, reason)
    VALUES ('RECURRING_TEMPLATE', _template_id, 'RECURRING_GENERATION_SKIPPED', jsonb_build_object('reference_date', _reference_date), auth.uid(), 'Competência já gerada');
    RETURN NULL;
  END IF;

  v_user := COALESCE(auth.uid(), t.created_by);

  IF t.type = 'RECEIVABLE' THEN
    INSERT INTO public.accounts_receivable(
      organization_id, origin_type, customer_id, description, category_id, cost_center_id,
      total_amount, issue_date, first_due_date, installment_count, status,
      fiscal_invoice_required, fiscal_invoice_status, notes, created_by,
      recurring_template_id, reference_month, auto_generated, payment_method_id
    ) VALUES (
      t.organization_id, 'RECURRING', t.customer_id, t.description, t.category_id, t.cost_center_id,
      t.amount, CURRENT_DATE, _reference_date, 1, 'OPEN',
      COALESCE(t.fiscal_invoice_required, false),
      CASE WHEN COALESCE(t.fiscal_invoice_required, false) THEN 'PENDING' ELSE 'NOT_REQUIRED' END,
      t.notes, v_user,
      t.id, date_trunc('month', _reference_date)::DATE, NOT _is_manual, t.payment_method_id
    ) RETURNING id INTO v_new_id;

    INSERT INTO public.recurring_generation_log(template_id, generated_entity_type, generated_entity_id, reference_date, amount, status, generated_by)
    VALUES (_template_id, 'RECEIVABLE', v_new_id, _reference_date, t.amount, 'SUCCESS', v_user);

    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by)
    VALUES ('RECURRING_TEMPLATE', _template_id, 'RECURRING_RECEIVABLE_GENERATED',
            jsonb_build_object('receivable_id', v_new_id, 'reference_date', _reference_date, 'amount', t.amount, 'manual', _is_manual),
            v_user);
  ELSE
    INSERT INTO public.accounts_payable(
      organization_id, origin_type, supplier_name, description, category_id, cost_center_id,
      total_amount, issue_date, first_due_date, installment_count, status,
      notes, created_by,
      recurring_template_id, reference_month, auto_generated
    ) VALUES (
      t.organization_id, 'RECURRING', t.supplier_name, t.description, t.category_id, t.cost_center_id,
      t.amount, CURRENT_DATE, _reference_date, 1, 'OPEN',
      t.notes, v_user,
      t.id, date_trunc('month', _reference_date)::DATE, NOT _is_manual
    ) RETURNING id INTO v_new_id;

    INSERT INTO public.recurring_generation_log(template_id, generated_entity_type, generated_entity_id, reference_date, amount, status, generated_by)
    VALUES (_template_id, 'PAYABLE', v_new_id, _reference_date, t.amount, 'SUCCESS', v_user);

    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by)
    VALUES ('RECURRING_TEMPLATE', _template_id, 'RECURRING_PAYABLE_GENERATED',
            jsonb_build_object('payable_id', v_new_id, 'reference_date', _reference_date, 'amount', t.amount, 'manual', _is_manual),
            v_user);
  END IF;

  UPDATE public.recurring_financial_templates
    SET next_generation_date = public.fn_calc_next_generation_date(t.recurrence_frequency, _reference_date, t.due_day),
        updated_at = now()
    WHERE id = _template_id;

  UPDATE public.recurring_financial_templates
    SET active = false
    WHERE id = _template_id AND end_date IS NOT NULL AND next_generation_date > end_date;

  RETURN v_new_id;
END $function$

CREATE OR REPLACE FUNCTION public.fn_h6b_reconciliacao_valor_faturavel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_canon jsonb;
BEGIN
  IF NEW.status = 'reconciliada' AND NEW.valor_faturavel_max IS NULL THEN
    v_canon := public.fn_entrega_valor_faturavel_v1(NEW.entrega_id);
    IF (v_canon->>'valor') IS NOT NULL THEN
      NEW.valor_faturavel_max  := round((v_canon->>'valor')::numeric, 2);
      NEW.valor_faturavel_origem := v_canon->>'origem';
      NEW.valor_faturavel_metodo := v_canon->'metodo';
    ELSE
      NEW.valor_faturavel_origem := 'indisponivel';
      NEW.valor_faturavel_metodo := v_canon;
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_h7j_fiscal_invoice_delete_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text := coalesce(OLD.normalized_status, OLD.status, 'DRAFT');
BEGIN
  IF v_status <> 'DRAFT'
     OR OLD.status <> 'DRAFT'
     OR OLD.access_key IS NOT NULL
     OR OLD.invoice_number IS NOT NULL
     OR OLD.authorized_at IS NOT NULL
     OR OLD.canceled_at IS NOT NULL
     OR OLD.rejected_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'FISCAL_DOCUMENT_DELETE_FORBIDDEN: documento fiscal com trilha (status=%) nao pode ser excluido.', v_status;
  END IF;

  IF EXISTS (SELECT 1 FROM public.fiscal_events e WHERE e.fiscal_invoice_id = OLD.id) THEN
    RAISE EXCEPTION 'FISCAL_DOCUMENT_DELETE_FORBIDDEN: documento fiscal possui eventos registrados.';
  END IF;

  IF to_regclass('public.fiscal_sefaz_transmissions') IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.fiscal_sefaz_transmissions t WHERE t.fiscal_invoice_id = OLD.id) THEN
      RAISE EXCEPTION 'FISCAL_DOCUMENT_DELETE_FORBIDDEN: documento fiscal possui transmissoes SEFAZ.';
    END IF;
  END IF;

  IF to_regclass('public.fiscal_number_reservations') IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.fiscal_number_reservations r WHERE r.fiscal_invoice_id = OLD.id) THEN
      RAISE EXCEPTION 'FISCAL_DOCUMENT_DELETE_FORBIDDEN: documento fiscal possui numeracao reservada.';
    END IF;
  END IF;

  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_notify_lab_on_programacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE org uuid; prod text; cli text; BEGIN
 IF NEW.status::text<>'aguardando' THEN RETURN NEW; END IF;
 org:=platform_private.notification_source_org('programacao_producao',NEW.id);
 IF org IS NULL THEN RETURN NEW; END IF;
 SELECT nome INTO prod FROM public.produtos WHERE id=NEW.produto_id;
 SELECT c.nome INTO cli FROM public.ordens_servico o JOIN public.clientes c ON c.id=o.cliente_id AND c.organization_id=org WHERE o.id=NEW.ordem_servico_id;
 INSERT INTO public.notificacoes_operacionais(usuario_id,tipo,titulo,mensagem,link,source_type,source_id)
 SELECT DISTINCT ur.user_id,'nova_demanda_producao','Nova demanda de produção',coalesce(prod,'Bioinsumo')||coalesce(' · '||cli,'')||coalesce(' · '||round(NEW.volume_necessario/1000.0,1)::text||' L',''),'/pcp?coluna=aguardando','programacao_producao',NEW.id
 FROM public.user_roles ur WHERE ur.role IN ('producao','administrador','gestor') AND platform_private.notification_user_ok(ur.user_id,org);
 RETURN NEW; END $function$

CREATE OR REPLACE FUNCTION public.fn_recalc_payable_installment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inst public.accounts_payable_installments%ROWTYPE;
  v_total_pago numeric(14,2);
  v_total_desc numeric(14,2);
  v_total_juros numeric(14,2);
  v_total_multa numeric(14,2);
  v_status text;
  v_inst_id uuid := COALESCE(NEW.installment_id, OLD.installment_id);
  v_parent_id uuid;
  v_open int; v_partial int; v_paid int; v_canc int; v_total int;
BEGIN
  SELECT * INTO v_inst FROM public.accounts_payable_installments WHERE id = v_inst_id;
  IF NOT FOUND THEN RETURN COALESCE(NEW, OLD); END IF;

  SELECT COALESCE(SUM(amount_paid),0), COALESCE(SUM(discount_amount),0),
         COALESCE(SUM(interest_amount),0), COALESCE(SUM(penalty_amount),0)
    INTO v_total_pago, v_total_desc, v_total_juros, v_total_multa
    FROM public.payable_payments WHERE installment_id = v_inst_id;

  IF (v_total_pago + v_total_desc) >= (v_inst.original_amount + v_total_juros + v_total_multa) THEN v_status := 'PAID';
  ELSIF v_total_pago > 0 THEN v_status := 'PARTIAL';
  ELSE v_status := CASE WHEN v_inst.due_date < (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date THEN 'OVERDUE' ELSE 'OPEN' END;
  END IF;

  UPDATE public.accounts_payable_installments
    SET paid_amount = v_total_pago, discount_amount = v_total_desc,
        interest_amount = v_total_juros, penalty_amount = v_total_multa,
        status = v_status,
        paid_at = CASE WHEN v_status='PAID' THEN now() ELSE NULL END
    WHERE id = v_inst_id;

  v_parent_id := v_inst.payable_id;
  SELECT count(*) FILTER (WHERE status='OPEN'),
         count(*) FILTER (WHERE status='PARTIAL'),
         count(*) FILTER (WHERE status='PAID'),
         count(*) FILTER (WHERE status='CANCELED'),
         count(*)
    INTO v_open, v_partial, v_paid, v_canc, v_total
    FROM public.accounts_payable_installments WHERE payable_id = v_parent_id;

  UPDATE public.accounts_payable SET status = CASE
    WHEN v_canc = v_total THEN 'CANCELED'
    WHEN (v_paid + v_canc) = v_total AND v_paid > 0 THEN 'PAID'
    WHEN v_paid > 0 OR v_partial > 0 THEN 'PARTIAL'
    WHEN EXISTS (SELECT 1 FROM public.accounts_payable_installments WHERE payable_id = v_parent_id AND status='OVERDUE') THEN 'OVERDUE'
    ELSE 'OPEN'
  END WHERE id = v_parent_id AND status <> 'CANCELED';

  RETURN COALESCE(NEW, OLD);
END $function$

CREATE OR REPLACE FUNCTION public.fn_recalc_receivable_installment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inst public.accounts_receivable_installments%ROWTYPE;
  v_total_recebido numeric(14,2);
  v_total_desc numeric(14,2);
  v_total_juros numeric(14,2);
  v_total_multa numeric(14,2);
  v_status text;
  v_inst_id uuid := COALESCE(NEW.installment_id, OLD.installment_id);
  v_parent_id uuid;
  v_open int;
  v_partial int;
  v_paid int;
  v_canc int;
  v_total int;
BEGIN
  SELECT * INTO v_inst FROM public.accounts_receivable_installments WHERE id = v_inst_id;
  IF NOT FOUND THEN RETURN COALESCE(NEW, OLD); END IF;

  SELECT COALESCE(SUM(amount_received),0), COALESCE(SUM(discount_amount),0),
         COALESCE(SUM(interest_amount),0), COALESCE(SUM(penalty_amount),0)
    INTO v_total_recebido, v_total_desc, v_total_juros, v_total_multa
    FROM public.receivable_payments WHERE installment_id = v_inst_id;

  IF (v_total_recebido + v_total_desc) >= (v_inst.original_amount + v_total_juros + v_total_multa) THEN
    v_status := 'PAID';
  ELSIF v_total_recebido > 0 THEN
    v_status := 'PARTIAL';
  ELSE
    v_status := CASE WHEN v_inst.due_date < (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date THEN 'OVERDUE' ELSE 'OPEN' END;
  END IF;

  UPDATE public.accounts_receivable_installments
    SET received_amount = v_total_recebido,
        discount_amount = v_total_desc,
        interest_amount = v_total_juros,
        penalty_amount = v_total_multa,
        status = v_status,
        paid_at = CASE WHEN v_status = 'PAID' THEN now() ELSE NULL END
    WHERE id = v_inst_id;

  -- Recalcular pai
  v_parent_id := v_inst.receivable_id;
  SELECT count(*) FILTER (WHERE status='OPEN'),
         count(*) FILTER (WHERE status='PARTIAL'),
         count(*) FILTER (WHERE status='PAID'),
         count(*) FILTER (WHERE status='CANCELED'),
         count(*)
    INTO v_open, v_partial, v_paid, v_canc, v_total
    FROM public.accounts_receivable_installments WHERE receivable_id = v_parent_id;

  UPDATE public.accounts_receivable SET status = CASE
    WHEN v_canc = v_total THEN 'CANCELED'
    WHEN (v_paid + v_canc) = v_total AND v_paid > 0 THEN 'PAID'
    WHEN v_paid > 0 OR v_partial > 0 THEN 'PARTIAL'
    WHEN EXISTS (SELECT 1 FROM public.accounts_receivable_installments WHERE receivable_id = v_parent_id AND status='OVERDUE') THEN 'OVERDUE'
    ELSE 'OPEN'
  END WHERE id = v_parent_id AND status <> 'CANCELED';

  RETURN COALESCE(NEW, OLD);
END $function$

CREATE OR REPLACE FUNCTION public.fn_recurring_generation_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by)
    VALUES ('RECURRING_LOG', NEW.id, 'GENERATION_LOG_CREATED', to_jsonb(NEW), auth.uid());
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, old_data, new_data, performed_by)
    VALUES ('RECURRING_LOG', NEW.id, 'GENERATION_LOG_UPDATED', to_jsonb(OLD), to_jsonb(NEW), auth.uid());
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, old_data, performed_by)
    VALUES ('RECURRING_LOG', OLD.id, 'GENERATION_LOG_DELETED', to_jsonb(OLD), auth.uid());
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_recurring_template_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'RECURRING_TEMPLATE_CREATED';
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by)
    VALUES ('RECURRING_TEMPLATE', NEW.id, v_action, to_jsonb(NEW), auth.uid());
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.active = true AND NEW.active = false AND NEW.end_date IS NOT NULL AND (OLD.end_date IS NULL OR OLD.end_date <> NEW.end_date) THEN
      v_action := 'RECURRING_TEMPLATE_CLOSED';
    ELSIF OLD.active = true AND NEW.active = false THEN
      v_action := 'RECURRING_TEMPLATE_PAUSED';
    ELSIF OLD.active = false AND NEW.active = true THEN
      v_action := 'RECURRING_TEMPLATE_REACTIVATED';
    ELSE
      v_action := 'RECURRING_TEMPLATE_UPDATED';
    END IF;
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, old_data, new_data, performed_by)
    VALUES ('RECURRING_TEMPLATE', NEW.id, v_action, to_jsonb(OLD), to_jsonb(NEW), auth.uid());
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, old_data, performed_by)
    VALUES ('RECURRING_TEMPLATE', OLD.id, 'RECURRING_TEMPLATE_DELETED', to_jsonb(OLD), auth.uid());
    RETURN OLD;
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.fn_reverse_payment(_payment_id uuid, _kind text, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := platform_private.h15_actor_organization();
  v_new_id uuid;
  v_row record;
  v_inst_status text;
  v_prev record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão obrigatória.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NOT public.is_financial_staff(v_uid) THEN
    RAISE EXCEPTION 'Apenas administrador, gestor ou financeiro podem estornar uma baixa.'
      USING ERRCODE='insufficient_privilege';
  END IF;
  IF _reason IS NULL OR length(trim(_reason)) < 5 THEN
    RAISE EXCEPTION 'Informe um motivo (mín. 5 caracteres) para o estorno.'
      USING ERRCODE='check_violation';
  END IF;
  IF _kind IS NULL OR _kind NOT IN ('receivable','payable') THEN
    RAISE EXCEPTION 'Tipo inválido: %', _kind;
  END IF;

  IF v_org IS NULL THEN RAISE EXCEPTION 'FINANCIAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
  IF _kind='receivable' THEN
    IF NOT EXISTS (SELECT 1 FROM public.receivable_payments WHERE id=_payment_id AND organization_id=v_org) THEN
      RAISE EXCEPTION 'FINANCIAL_SCOPE_DENIED' USING ERRCODE='42501';
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.payable_payments WHERE id=_payment_id AND organization_id=v_org) THEN
      RAISE EXCEPTION 'FINANCIAL_SCOPE_DENIED' USING ERRCODE='42501';
    END IF;
  END IF;
  -- lock determinístico por intencao de reversao (mesma baixa original)
  PERFORM pg_advisory_xact_lock(hashtextextended('fin_reverse:' || _kind || ':' || _payment_id::text, 0));

  IF _kind = 'receivable' THEN
    SELECT * INTO v_row FROM public.receivable_payments WHERE id = _payment_id AND organization_id=v_org FOR UPDATE;
    IF v_row.id IS NULL THEN RAISE EXCEPTION 'Pagamento não encontrado.'; END IF;
    IF v_row.is_reversal THEN RAISE EXCEPTION 'Não é possível estornar um registro de estorno.'; END IF;

    -- replay estavel: mesma intencao -> devolve reversao existente
    SELECT id, reversal_reason INTO v_prev FROM public.receivable_payments
     WHERE reversed_payment_id = _payment_id AND is_reversal = true;
    IF v_prev.id IS NOT NULL THEN
      IF trim(COALESCE(v_prev.reversal_reason,'')) IS DISTINCT FROM trim(_reason) THEN
        RAISE EXCEPTION 'FIN_IDEMPOTENCY_CONFLICT: baixa já estornada com motivo divergente.'
          USING ERRCODE='check_violation';
      END IF;
      RETURN v_prev.id;
    END IF;

    SELECT status INTO v_inst_status FROM public.accounts_receivable_installments WHERE id = v_row.installment_id;
    IF v_inst_status = 'CANCELED' THEN
      RAISE EXCEPTION 'Não é possível estornar baixa de parcela cancelada.';
    END IF;

    INSERT INTO public.receivable_payments(
      organization_id, installment_id, payment_date, payment_method_id, bank_account_id,
      amount_received, discount_amount, interest_amount, penalty_amount,
      notes, created_by, is_reversal, reversed_payment_id, reversal_reason
    ) VALUES (
      v_org, v_row.installment_id, (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date, v_row.payment_method_id, v_row.bank_account_id,
      -v_row.amount_received, -COALESCE(v_row.discount_amount,0),
      -COALESCE(v_row.interest_amount,0), -COALESCE(v_row.penalty_amount,0),
      '[ESTORNO] '||_reason, v_uid, true, _payment_id, _reason
    ) RETURNING id INTO v_new_id;

  ELSE
    SELECT * INTO v_row FROM public.payable_payments WHERE id = _payment_id AND organization_id=v_org FOR UPDATE;
    IF v_row.id IS NULL THEN RAISE EXCEPTION 'Pagamento não encontrado.'; END IF;
    IF v_row.is_reversal THEN RAISE EXCEPTION 'Não é possível estornar um registro de estorno.'; END IF;

    SELECT id, reversal_reason INTO v_prev FROM public.payable_payments
     WHERE reversed_payment_id = _payment_id AND is_reversal = true;
    IF v_prev.id IS NOT NULL THEN
      IF trim(COALESCE(v_prev.reversal_reason,'')) IS DISTINCT FROM trim(_reason) THEN
        RAISE EXCEPTION 'FIN_IDEMPOTENCY_CONFLICT: baixa já estornada com motivo divergente.'
          USING ERRCODE='check_violation';
      END IF;
      RETURN v_prev.id;
    END IF;

    SELECT status INTO v_inst_status FROM public.accounts_payable_installments WHERE id = v_row.installment_id;
    IF v_inst_status = 'CANCELED' THEN
      RAISE EXCEPTION 'Não é possível estornar baixa de parcela cancelada.';
    END IF;

    INSERT INTO public.payable_payments(
      organization_id, installment_id, payment_date, payment_method_id, bank_account_id,
      amount_paid, discount_amount, interest_amount, penalty_amount,
      notes, created_by, is_reversal, reversed_payment_id, reversal_reason
    ) VALUES (
      v_org, v_row.installment_id, (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date, v_row.payment_method_id, v_row.bank_account_id,
      -v_row.amount_paid, -COALESCE(v_row.discount_amount,0),
      -COALESCE(v_row.interest_amount,0), -COALESCE(v_row.penalty_amount,0),
      '[ESTORNO] '||_reason, v_uid, true, _payment_id, _reason
    ) RETURNING id INTO v_new_id;
  END IF;

  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by)
  VALUES (
    CASE WHEN _kind='receivable' THEN 'receivable_payments' ELSE 'payable_payments' END,
    v_new_id, 'PAYMENT_REVERSAL_CREATED',
    jsonb_build_object('reversed_payment_id', _payment_id, 'reason', _reason),
    v_uid
  );

  RETURN v_new_id;
END $function$

CREATE OR REPLACE FUNCTION public.fn_revert_recurring_generation(p_log_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_log public.recurring_generation_log%ROWTYPE;
  v_status TEXT;
BEGIN
  -- 1. Verifica permissão
  IF NOT public.is_financial_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  -- 2. Busca o log
  SELECT * INTO v_log FROM public.recurring_generation_log l WHERE l.id = p_log_id
    AND EXISTS (SELECT 1 FROM public.recurring_financial_templates t WHERE t.id=l.template_id
      AND t.organization_id=platform_private.h15_actor_organization()) FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Log de geração não encontrado';
  END IF;

  IF v_log.status <> 'SUCCESS' THEN
    RAISE EXCEPTION 'Apenas gerações com sucesso podem ser revertidas';
  END IF;

  -- 3. Verifica se o título gerado ainda pode ser excluído (status deve ser OPEN)
  IF v_log.generated_entity_type = 'RECEIVABLE' THEN
    SELECT status INTO v_status FROM public.accounts_receivable WHERE id = v_log.generated_entity_id;
    IF v_status <> 'OPEN' THEN
      RAISE EXCEPTION 'Título de receita não pode ser revertido pois não está mais Aberto (Status: %)', v_status;
    END IF;

    -- Deleta o título (o trigger de auditoria do accounts_receivable cuidará do log de DELETE)
    DELETE FROM public.accounts_receivable WHERE id = v_log.generated_entity_id;

  ELSIF v_log.generated_entity_type = 'PAYABLE' THEN
    SELECT status INTO v_status FROM public.accounts_payable WHERE id = v_log.generated_entity_id;
    IF v_status <> 'OPEN' THEN
      RAISE EXCEPTION 'Título de despesa não pode ser revertido pois não está mais Aberto (Status: %)', v_status;
    END IF;

    DELETE FROM public.accounts_payable WHERE id = v_log.generated_entity_id;
  END IF;

  -- 4. Log de auditoria da reversão
  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, old_data, performed_by, reason)
  VALUES ('RECURRING_TEMPLATE', v_log.template_id, 'RECURRING_GENERATION_REVERSED', to_jsonb(v_log), auth.uid(), 'Reversão manual solicitada pelo gestor');

  -- 5. Remove o log para permitir nova geração na mesma data (o trigger de log_audit registrará DELETED)
  DELETE FROM public.recurring_generation_log WHERE id = p_log_id;

END;
$function$

CREATE OR REPLACE FUNCTION public.fn_set_initial_next_generation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_initial DATE;
BEGIN
  IF NEW.next_generation_date IS NULL THEN
    v_initial := NEW.start_date;
    IF NEW.due_day IS NOT NULL AND NEW.recurrence_frequency IN ('MONTHLY','QUARTERLY','YEARLY') THEN
      BEGIN
        v_initial := make_date(EXTRACT(YEAR FROM v_initial)::INT, EXTRACT(MONTH FROM v_initial)::INT,
          LEAST(NEW.due_day, EXTRACT(DAY FROM (date_trunc('month', v_initial) + INTERVAL '1 month - 1 day'))::INT));
      EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;
    NEW.next_generation_date := v_initial;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_sync_entrega_financial_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- bloqueia troca de receivable_id já vinculado
  IF TG_OP = 'UPDATE'
     AND OLD.receivable_id IS NOT NULL
     AND NEW.receivable_id IS DISTINCT FROM OLD.receivable_id THEN
    RAISE EXCEPTION 'Esta entrega já possui faturamento gerado e não pode ser alterada.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- vinculou receivable agora => BILLED
  IF (TG_OP = 'INSERT' AND NEW.receivable_id IS NOT NULL)
     OR (TG_OP = 'UPDATE' AND OLD.receivable_id IS NULL AND NEW.receivable_id IS NOT NULL) THEN
    NEW.financial_status := 'BILLED';
    NEW.billing_generated_at := COALESCE(NEW.billing_generated_at, now());
    NEW.billing_generated_by := COALESCE(NEW.billing_generated_by, auth.uid());
  END IF;

  -- entrega cancelada
  IF NEW.status::text = 'cancelada' THEN
    NEW.financial_status := 'CANCELED';
  END IF;

  -- valida NOT_BILLABLE
  IF NEW.financial_status = 'NOT_BILLABLE'
     AND (NEW.not_billable_reason IS NULL OR length(trim(NEW.not_billable_reason)) = 0) THEN
    RAISE EXCEPTION 'Informe o motivo para marcar a entrega como sem cobrança.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- default quando não definido
  IF NEW.financial_status IS NULL THEN
    NEW.financial_status := 'PENDING_BILLING';
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_sync_os_classica_downstream()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prog_id uuid;
  v_lote_id uuid;
BEGIN
  IF (OLD.status IS NOT DISTINCT FROM NEW.status) THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_prog_id FROM public.programacao_producao
   WHERE ordem_servico_id = NEW.id ORDER BY created_at DESC LIMIT 1;

  IF v_prog_id IS NULL
     AND NEW.status::text IN ('aprovada','programada','em_producao','em_cq','envase','pronto_entrega','entregue','finalizada')
     AND (NEW.produto_id IS NOT NULL OR NEW.microrganismo_id IS NOT NULL) THEN
    INSERT INTO public.programacao_producao
      (produto_id, microrganismo_id, volume_necessario, data_programada, status, ordem_servico_id)
    VALUES
      (NEW.produto_id, NEW.microrganismo_id, NEW.volume_total_ml,
       COALESCE(NEW.data_programada, CURRENT_DATE), 'aguardando', NEW.id)
    RETURNING id INTO v_prog_id;
  END IF;

  IF v_prog_id IS NOT NULL THEN
    SELECT id INTO v_lote_id FROM public.lotes
      WHERE programacao_id = v_prog_id ORDER BY created_at DESC LIMIT 1;
  END IF;

  CASE NEW.status::text
    WHEN 'aprovada' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'aguardando' WHERE id = v_prog_id;
      END IF;
    WHEN 'programada' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao
           SET status = 'aguardando',
               data_programada = COALESCE(NEW.data_programada, data_programada, CURRENT_DATE)
         WHERE id = v_prog_id;
      END IF;
    WHEN 'em_producao' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'em_producao' WHERE id = v_prog_id;
      END IF;
      IF v_lote_id IS NULL AND (NEW.produto_id IS NOT NULL OR NEW.microrganismo_id IS NOT NULL) THEN
        INSERT INTO public.lotes (codigo_lote, produto_id, microrganismo_id, programacao_id, status, volume_produzido, data_producao)
        VALUES (public.gerar_codigo_lote(), NEW.produto_id, NEW.microrganismo_id, v_prog_id,
                'em_producao', NEW.volume_total_ml, CURRENT_DATE);
      END IF;
    WHEN 'em_cq' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'aguardando_cq' WHERE id = v_prog_id;
      END IF;
      IF v_lote_id IS NOT NULL THEN
        UPDATE public.lotes SET status = 'aguardando_cq' WHERE id = v_lote_id;
      END IF;
    WHEN 'envase' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'aprovado' WHERE id = v_prog_id;
      END IF;
    ELSE
      NULL;
  END CASE;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_sync_receipt_aliases()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.receivable_payment_id IS NULL AND NEW.payment_id IS NOT NULL THEN
    NEW.receivable_payment_id := NEW.payment_id;
  ELSIF NEW.payment_id IS NULL AND NEW.receivable_payment_id IS NOT NULL THEN
    NEW.payment_id := NEW.receivable_payment_id;
  END IF;
  IF NEW.description IS NULL OR length(trim(NEW.description)) = 0 THEN
    NEW.description := 'Recibo nº ' || COALESCE(NEW.receipt_number, '—');
