CREATE OR REPLACE FUNCTION public.fn_validate_entrega_confirmacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_anexos int;
BEGIN
  IF NEW.status::text = 'entregue'
     AND (TG_OP = 'INSERT' OR OLD.status::text IS DISTINCT FROM 'entregue') THEN

    IF TG_OP = 'UPDATE' AND OLD.status::text = 'cancelada' THEN
      RAISE EXCEPTION 'Não é possível confirmar uma entrega cancelada.'
        USING ERRCODE = 'check_violation';
    END IF;

    IF COALESCE(TRIM(NEW.recebido_por_nome), '') = '' THEN
      RAISE EXCEPTION 'Informe o nome de quem recebeu a entrega.'
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.confirmado_por IS NULL THEN
      RAISE EXCEPTION 'A entrega precisa ser confirmada por um usuário autenticado.'
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.entregue_em IS NULL THEN
      NEW.entregue_em := now();
    END IF;

    IF NEW.comprovante_entrega_obrigatorio THEN
      SELECT count(*) INTO v_anexos
        FROM public.entrega_documentos
        WHERE entrega_id = NEW.id;
      IF v_anexos = 0 THEN
        RAISE EXCEPTION 'É obrigatório anexar pelo menos um comprovante para confirmar esta entrega.'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validate_entrega_estoque()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_estoque_id uuid;
  v_qtd_fisica_disponivel numeric;
  v_qtd_reservada_os numeric;
  v_qtd_ja_entregue_lote_os numeric;
  v_lote_codigo text;
BEGIN
  -- Se a entrega já está sendo criada/atualizada como cancelada, não validar saldo
  IF NEW.status::text = 'cancelada' THEN
    RETURN NEW;
  END IF;

  v_estoque_id := NEW.estoque_produto_id;

  IF v_estoque_id IS NULL THEN
    RAISE EXCEPTION 'ID do estoque não informado na entrega.' USING ERRCODE = 'check_violation';
  END IF;

  SELECT 
    ep.quantidade, 
    ep.quantidade_reservada,
    l.codigo_lote
  INTO 
    v_qtd_fisica_disponivel, 
    v_qtd_reservada_os,
    v_lote_codigo
  FROM public.estoque_produto ep
  JOIN public.lotes l ON l.id = ep.lote_id
  WHERE ep.id = v_estoque_id;

  -- Acumula somente entregas válidas (ignora canceladas)
  SELECT COALESCE(SUM(quantidade_entregue), 0)
  INTO v_qtd_ja_entregue_lote_os
  FROM public.entregas
  WHERE estoque_produto_id = v_estoque_id 
    AND ordem_servico_id = NEW.ordem_servico_id
    AND id <> NEW.id
    AND status::text <> 'cancelada';

  IF NEW.quantidade_entregue > v_qtd_fisica_disponivel THEN
    RAISE EXCEPTION 'Saldo físico insuficiente no lote %. Disponível: %, Solicitado: %.',
      v_lote_codigo, v_qtd_fisica_disponivel, NEW.quantidade_entregue
      USING ERRCODE = 'check_violation';
  END IF;

  IF (v_qtd_ja_entregue_lote_os + NEW.quantidade_entregue) > v_qtd_reservada_os THEN
    RAISE EXCEPTION 'Quantidade excede o saldo reservado para esta Ordem de Serviço no lote %. Reservado total: %, Já entregue: %, Saldo restante: %.',
      v_lote_codigo, v_qtd_reservada_os, v_qtd_ja_entregue_lote_os, (v_qtd_reservada_os - v_qtd_ja_entregue_lote_os)
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validate_envase_cq()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_lote_status TEXT;
    v_cq_resultado TEXT;
BEGIN
    SELECT status INTO v_lote_status FROM public.lotes WHERE id = NEW.lote_id;

    SELECT resultado::text INTO v_cq_resultado
      FROM public.controle_qualidade
     WHERE lote_id = NEW.lote_id
     ORDER BY created_at DESC, seq DESC
     LIMIT 1;

    IF v_lote_status <> 'aprovado' OR v_cq_resultado IS NULL OR v_cq_resultado <> 'aprovado' THEN
        RAISE EXCEPTION 'O lote % não possui Controle de Qualidade aprovado. O envase não é permitido.',
            (SELECT codigo_lote FROM public.lotes WHERE id = NEW.lote_id);
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validate_envase_volume()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_produzido numeric;
  v_envasado numeric;
  v_novo numeric;
  v_codigo text;
  v_saldo numeric;
BEGIN
  IF NEW.quantidade IS NULL OR NEW.quantidade <= 0 THEN
    RAISE EXCEPTION 'A quantidade do envase deve ser maior que zero.' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.volume_por_unidade IS NULL OR NEW.volume_por_unidade <= 0 THEN
    RAISE EXCEPTION 'O volume por unidade deve ser maior que zero.' USING ERRCODE = 'check_violation';
  END IF;

  -- H5-B01/B02: serializa qualquer INSERT de envase (inclusive direto via RLS) pela linha do lote.
  -- Ordem de lock compatível com rpc_cockpit_registrar_envase_v1 (programacao -> lote).
  SELECT volume_produzido, codigo_lote INTO v_produzido, v_codigo
  FROM public.lotes WHERE id = NEW.lote_id FOR UPDATE;

  IF v_codigo IS NULL AND v_produzido IS NULL THEN
    RAISE EXCEPTION 'Lote % inexistente para envase.', NEW.lote_id USING ERRCODE = 'check_violation';
  END IF;

  IF v_produzido IS NULL OR v_produzido <= 0 THEN
    RAISE EXCEPTION 'O lote % não possui volume produzido informado. Registre a produção antes de envasar.', COALESCE(v_codigo,'(desconhecido)')
      USING ERRCODE = 'check_violation';
  END IF;

  v_envasado := public.lote_volume_envasado(NEW.lote_id);
  v_novo := COALESCE(NEW.volume_por_unidade,0) * COALESCE(NEW.quantidade,0);
  v_saldo := v_produzido - v_envasado;

  IF (v_envasado + v_novo) > v_produzido THEN
    RAISE EXCEPTION 'Envase excede o volume produzido do lote %. Produzido: % L, já envasado: % L, saldo disponível: % L, solicitado: % L.',
      COALESCE(v_codigo,'(desconhecido)'),
      ROUND(v_produzido/1000.0, 2),
      ROUND(v_envasado/1000.0, 2),
      ROUND(v_saldo/1000.0, 2),
      ROUND(v_novo/1000.0, 2)
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.gen_numero_solicitacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year text;
  v_seq bigint;
BEGIN
  IF NEW.numero_solicitacao IS NULL OR NEW.numero_solicitacao = '' THEN
    v_year := to_char(now(), 'YYYY');
    v_seq := nextval('public.solicitacoes_numero_seq');
    NEW.numero_solicitacao := 'SOL-' || v_year || '-' || lpad(v_seq::text, 6, '0');
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.gerar_codigo_lote(_ano integer DEFAULT (EXTRACT(year FROM now()))::integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_prefix text := 'LT-' || _ano::text || '-';
  v_next int;
BEGIN
  IF _ano IS NULL THEN
    RAISE EXCEPTION 'LOTE_ANO_INVALIDO';
  END IF;

  -- Serializa o cálculo sequencial por ano dentro da transação chamadora.
  PERFORM pg_advisory_xact_lock(hashtext('gerar_codigo_lote:' || _ano::text));

  SELECT COALESCE(MAX(NULLIF(regexp_replace(split_part(codigo_lote, '-', 3), '\D', '', 'g'), '')::int), 0) + 1
    INTO v_next
    FROM public.lotes
   WHERE codigo_lote LIKE v_prefix || '%';

  RETURN v_prefix || lpad(v_next::text, 4, '0');
END;
$function$

CREATE OR REPLACE FUNCTION public.get_financial_report_data(p_report_type text, p_start_date date, p_end_date date, p_customer_id uuid DEFAULT NULL::uuid, p_category_id uuid DEFAULT NULL::uuid, p_cost_center_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_regime text DEFAULT 'CASH'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_filters jsonb; v_rows jsonb; v_summary jsonb;
BEGIN
  IF NOT is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  IF p_start_date IS NULL OR p_end_date IS NULL THEN
    RAISE EXCEPTION 'Datas inicial e final são obrigatórias'; END IF;
  IF p_end_date < p_start_date THEN
    RAISE EXCEPTION 'Data final não pode ser menor que data inicial'; END IF;
  v_filters := jsonb_build_object(
    'start_date', p_start_date, 'end_date', p_end_date,
    'customer_id', p_customer_id, 'category_id', p_category_id,
    'cost_center_id', p_cost_center_id, 'status', p_status, 'regime', p_regime
  );
  CASE upper(p_report_type)
    WHEN 'MONTHLY_FINANCIAL' THEN
      v_summary := get_report_monthly_financial(p_start_date, p_end_date, p_cost_center_id, p_regime);
    WHEN 'ACCOUNTS_RECEIVABLE' THEN
      SELECT jsonb_agg(to_jsonb(t)) INTO v_rows FROM get_report_receivables(v_filters) t;
    WHEN 'ACCOUNTS_PAYABLE' THEN
      SELECT jsonb_agg(to_jsonb(t)) INTO v_rows FROM get_report_payables(v_filters) t;
    WHEN 'CASHFLOW' THEN
      v_summary := get_financial_cashflow(p_start_date, p_end_date, 'PROJECTED', 'DAY');
    WHEN 'DRE' THEN
      v_summary := get_financial_dre_summary(p_start_date, p_end_date, p_regime, p_cost_center_id);
    WHEN 'INADIMPLENCIA' THEN
      SELECT jsonb_agg(to_jsonb(t)) INTO v_rows FROM get_report_delinquency(p_end_date) t;
    WHEN 'FISCAL_PENDING' THEN
      SELECT jsonb_agg(to_jsonb(t)) INTO v_rows FROM get_report_nfe_pending(v_filters) t;
    WHEN 'DELIVERY_BILLING' THEN
      v_summary := (SELECT to_jsonb(x) FROM get_report_deliveries_billing_status(p_start_date, p_end_date) x);
    WHEN 'CUSTOMER_STATEMENT' THEN
      IF p_customer_id IS NULL THEN RAISE EXCEPTION 'Cliente é obrigatório para extrato'; END IF;
      v_summary := get_report_customer_statement(p_customer_id, p_start_date, p_end_date);
    WHEN 'ACCOUNTABILITY_STATEMENT' THEN
      IF p_customer_id IS NULL THEN RAISE EXCEPTION 'Cliente é obrigatório para prestação de contas'; END IF;
      v_summary := get_report_accountability(jsonb_build_object(
        'customer_id', p_customer_id, 'from', p_start_date, 'to', p_end_date));
    ELSE RAISE EXCEPTION 'Tipo de relatório inválido: %', p_report_type;
  END CASE;
  PERFORM log_report_view(p_report_type, v_filters);
  RETURN jsonb_build_object(
    'report_type', p_report_type, 'filters', v_filters,
    'summary', COALESCE(v_summary, '{}'::jsonb),
    'rows', COALESCE(v_rows, '[]'::jsonb),
    'generated_at', now()
  );
END$function$

CREATE OR REPLACE FUNCTION public.get_report_accountability(_scope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r jsonb;
        _customer uuid := NULLIF(_scope->>'customer_id','')::uuid;
        _from date := (_scope->>'from')::date;
        _to date := (_scope->>'to')::date;
BEGIN
  IF NOT is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  SELECT jsonb_build_object(
    'scope', _scope,
    'summary', public.get_report_customer_statement(_customer, _from, _to)
  ) INTO r;
  RETURN r;
END;$function$

CREATE OR REPLACE FUNCTION public.issue_financial_receipt(_payment_id uuid, _description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid; v_payment record; v_installment record; v_receivable record; v_existing record; v_receipt_id uuid; v_desc text;
BEGIN
 v_org:=public.h15_actor_organization();
 IF v_org IS NULL OR NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_payment FROM public.receivable_payments WHERE id=_payment_id AND organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'Recebimento não encontrado' USING ERRCODE='42501'; END IF;
 IF v_payment.is_reversal THEN RAISE EXCEPTION 'Não é possível emitir recibo para estorno'; END IF;
 SELECT * INTO v_installment FROM public.accounts_receivable_installments WHERE id=v_payment.installment_id AND organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'Parcela não encontrada' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_receivable FROM public.accounts_receivable WHERE id=v_installment.receivable_id AND organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'Título não encontrado' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_existing FROM public.financial_receipts WHERE payment_id=_payment_id AND status='ISSUED' AND organization_id=v_org LIMIT 1;
 IF FOUND THEN RETURN jsonb_build_object('duplicate',true,'receipt_id',v_existing.id,'receipt_number',v_existing.receipt_number,'message','Recibo já emitido para este recebimento'); END IF;
 v_desc:=COALESCE(NULLIF(trim(_description),''),'Recebimento ref. parcela '||COALESCE(v_installment.installment_number::text,'—')||' de '||COALESCE(v_receivable.description,'título financeiro'));
 INSERT INTO public.financial_receipts(payment_id,receivable_payment_id,receivable_id,customer_id,amount,payment_date,payment_method_id,description,issued_by,status,organization_id)
 VALUES(_payment_id,_payment_id,v_installment.receivable_id,v_receivable.customer_id,v_payment.amount_received,v_payment.payment_date,v_payment.payment_method_id,v_desc,auth.uid(),'ISSUED',v_org) RETURNING id INTO v_receipt_id;
 INSERT INTO public.financial_audit_log(entity_type,entity_id,action,new_data,performed_by) VALUES('financial_receipts',v_receipt_id,'FINANCIAL_RECEIPT_ISSUED',jsonb_build_object('payment_id',_payment_id,'amount',v_payment.amount_received),auth.uid());
 RETURN jsonb_build_object('duplicate',false,'receipt_id',v_receipt_id,'receipt_number',(SELECT receipt_number FROM public.financial_receipts WHERE id=v_receipt_id AND organization_id=v_org));
END $function$

CREATE OR REPLACE FUNCTION public.log_catalog_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entidade text;
  v_id uuid;
BEGIN
