CREATE OR REPLACE FUNCTION public.tg_entrega_conf_lock_after_sign()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_eid uuid := coalesce(NEW.entrega_id, OLD.entrega_id);
BEGIN
  IF EXISTS (SELECT 1 FROM public.entrega_termos t
             WHERE t.entrega_id = v_eid AND t.status = 'assinado') THEN
    RAISE EXCEPTION 'conferencia_bloqueada: existe termo assinado para esta entrega'
      USING ERRCODE = 'raise_exception';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tg_entrega_termos_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'rascunho' THEN
      RAISE EXCEPTION 'termo_imutavel: documento % nao pode ser excluido', OLD.id
        USING ERRCODE = 'raise_exception';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status IN ('assinado','cancelado','substituido') THEN
    IF NEW.snapshot IS DISTINCT FROM OLD.snapshot
       OR NEW.snapshot_hash IS DISTINCT FROM OLD.snapshot_hash
       OR NEW.versao IS DISTINCT FROM OLD.versao
       OR NEW.template_versao IS DISTINCT FROM OLD.template_versao
       OR NEW.entrega_id IS DISTINCT FROM OLD.entrega_id
       OR NEW.recebedor_nome IS DISTINCT FROM OLD.recebedor_nome
       OR NEW.recebedor_documento IS DISTINCT FROM OLD.recebedor_documento
       OR NEW.assinatura_hash IS DISTINCT FROM OLD.assinatura_hash
       OR NEW.assinado_em IS DISTINCT FROM OLD.assinado_em
       OR NEW.assinado_por IS DISTINCT FROM OLD.assinado_por
       OR NEW.cobertura IS DISTINCT FROM OLD.cobertura THEN
      RAISE EXCEPTION 'termo_imutavel: documento assinado nao pode ser alterado'
        USING ERRCODE = 'raise_exception';
    END IF;
    -- PDF só pode ser gravado uma vez por versão
    IF OLD.pdf_path IS NOT NULL AND NEW.pdf_path IS DISTINCT FROM OLD.pdf_path THEN
      RAISE EXCEPTION 'termo_pdf_imutavel: ja existe PDF ativo para esta versao'
        USING ERRCODE = 'raise_exception';
    END IF;
    IF OLD.status <> 'assinado' AND NEW.status <> OLD.status THEN
      RAISE EXCEPTION 'termo_estado_terminal: transicao % -> % proibida', OLD.status, NEW.status
        USING ERRCODE = 'raise_exception';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tg_fiscal_certificates_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_action text;
  v_old    jsonb;
  v_new    jsonb;
BEGIN
  v_action := TG_OP;
  IF TG_OP = 'INSERT' THEN
    v_old := '{}'::jsonb;
    v_new := jsonb_build_object(
      'source_type', NEW.source_type,
      'environment', NEW.environment,
      'status',      NEW.status,
      'display_name',NEW.display_name,
      'fingerprint_sha256', NEW.fingerprint_sha256,
      'valid_until', NEW.valid_until,
      'is_active',   NEW.is_active
    );
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := jsonb_build_object('status', OLD.status, 'is_active', OLD.is_active, 'valid_until', OLD.valid_until);
    v_new := jsonb_build_object('status', NEW.status, 'is_active', NEW.is_active, 'valid_until', NEW.valid_until);
  ELSE
    RETURN NEW;
  END IF;

  INSERT INTO public.fiscal_audit_log (
    table_name, record_id, action, changed_by, old_values, new_values
  ) VALUES (
    'fiscal_certificates', COALESCE(NEW.id, OLD.id), v_action, auth.uid(), v_old, v_new
  );
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_fiscal_operation_policy_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.policy_status = 'PUBLISHED' THEN
      RAISE EXCEPTION 'FISCAL_POLICY_IMMUTABLE: politica publicada nao pode ser excluida (id=%)', OLD.id;
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.policy_status = 'PUBLISHED' AND NEW.policy_status = 'PUBLISHED' THEN
    IF (OLD.cfop, OLD.nature_operation, OLD.direction, OLD.origin_uf, OLD.destination_uf,
        OLD.crt, OLD.ncm_prefix, OLD.final_consumer, OLD.taxpayer_indicator,
        OLD.valid_from, OLD.valid_until, OLD.source_id, OLD.legal_basis)
       IS DISTINCT FROM
       (NEW.cfop, NEW.nature_operation, NEW.direction, NEW.origin_uf, NEW.destination_uf,
        NEW.crt, NEW.ncm_prefix, NEW.final_consumer, NEW.taxpayer_indicator,
        NEW.valid_from, NEW.valid_until, NEW.source_id, NEW.legal_basis) THEN
      RAISE EXCEPTION 'FISCAL_POLICY_IMMUTABLE: politica publicada e imutavel; crie nova vigencia (id=%)', OLD.id;
    END IF;
  END IF;
  IF OLD.policy_status = 'PUBLISHED' AND NEW.policy_status = 'DRAFT' THEN
    RAISE EXCEPTION 'FISCAL_POLICY_IMMUTABLE: politica publicada nao retorna a DRAFT (id=%)', OLD.id;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tg_fiscal_tax_rule_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status IN ('PUBLISHED','SUPERSEDED') THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_IMMUTABLE: versao publicada nao pode ser excluida (rule_key=% v=%)', OLD.rule_key, OLD.version;
    END IF;
    RETURN OLD;
  END IF;

  -- H7-101: máquina de estados fechada. Nenhum caminho reabilita histórico.
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    IF NOT (
         (OLD.status = 'DRAFT'     AND NEW.status IN ('PUBLISHED'))
      OR (OLD.status = 'PUBLISHED' AND NEW.status = 'SUPERSEDED')
    ) THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_STATUS_TRANSITION_FORBIDDEN: % -> % nao permitido (rule_key=% v=%)',
        OLD.status, NEW.status, OLD.rule_key, OLD.version
        USING HINT = 'Regra arquivada nunca volta a vigorar. Crie nova versao DRAFT e publique via rpc_fiscal_tax_rule_publish.';
    END IF;
    -- Publicação só pelo fluxo canônico (fonte oficial + SoD + aprovador).
    IF NEW.status = 'PUBLISHED' AND (NEW.published_by IS NULL OR NEW.published_at IS NULL) THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_PUBLISH_CHANNEL: publicacao exige rpc_fiscal_tax_rule_publish (autoria/aprovacao obrigatorias).';
    END IF;
  END IF;

  -- H7-101: conteúdo de versão publicada OU arquivada é imutável.
  IF OLD.status IN ('PUBLISHED','SUPERSEDED') THEN
    IF OLD.status = 'PUBLISHED' AND NEW.status = 'DRAFT' THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_IMMUTABLE: versao publicada nao retorna a DRAFT (rule_key=% v=%)', OLD.rule_key, OLD.version;
    END IF;
    IF (OLD.tax_kind, OLD.calc_mode, OLD.crt, OLD.origin_uf, OLD.destination_uf, OLD.ncm_prefix,
        OLD.product_category, OLD.final_consumer, OLD.taxpayer_indicator, OLD.cst, OLD.csosn,
        OLD.rate, OLD.base_reduction_pct, OLD.deferral_pct, OLD.mva_pct, OLD.fcp_rate,
        OLD.difal_dest_share_pct, OLD.legal_basis, OLD.source_id, OLD.valid_from, OLD.valid_until, OLD.version)
       IS DISTINCT FROM
       (NEW.tax_kind, NEW.calc_mode, NEW.crt, NEW.origin_uf, NEW.destination_uf, NEW.ncm_prefix,
        NEW.product_category, NEW.final_consumer, NEW.taxpayer_indicator, NEW.cst, NEW.csosn,
        NEW.rate, NEW.base_reduction_pct, NEW.deferral_pct, NEW.mva_pct, NEW.fcp_rate,
        NEW.difal_dest_share_pct, NEW.legal_basis, NEW.source_id, NEW.valid_from, NEW.valid_until, NEW.version) THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_IMMUTABLE: conteudo de versao % e imutavel; crie nova versao (rule_key=% v=%)',
        OLD.status, OLD.rule_key, OLD.version;
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.tg_fiscal_xml_runs_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: execucoes de XML sao append-only; DELETE proibido.';
  END IF;

  IF coalesce(current_setting('app.fiscal_xml_engine', true),'off') <> 'on' THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: atualize execucoes apenas via rpc_fiscal_xml_record_v1.';
  END IF;

  IF NEW.id <> OLD.id
     OR NEW.fiscal_invoice_id <> OLD.fiscal_invoice_id
     OR NEW.idempotency_key <> OLD.idempotency_key
     OR NEW.run_version <> OLD.run_version
     OR NEW.payload_sha256 <> OLD.payload_sha256
     OR NEW.payload::text <> OLD.payload::text
     OR NEW.access_key <> OLD.access_key
     OR NEW.environment_code <> OLD.environment_code
     OR NEW.engine_version <> OLD.engine_version
     OR NEW.prepared_at <> OLD.prepared_at
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.previous_run_id IS DISTINCT FROM OLD.previous_run_id THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: campos congelados nao podem ser alterados.';
  END IF;

  IF OLD.unsigned_sha256 IS NOT NULL AND NEW.unsigned_sha256 IS DISTINCT FROM OLD.unsigned_sha256 THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: hash do XML nao assinado ja registrado.';
  END IF;
  IF OLD.signed_sha256 IS NOT NULL AND NEW.signed_sha256 IS DISTINCT FROM OLD.signed_sha256 THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: hash do XML assinado ja registrado.';
  END IF;
  IF OLD.unsigned_path IS NOT NULL AND NEW.unsigned_path IS DISTINCT FROM OLD.unsigned_path THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: caminho do XML nao assinado ja registrado.';
  END IF;
  IF OLD.signed_path IS NOT NULL AND NEW.signed_path IS DISTINCT FROM OLD.signed_path THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: caminho do XML assinado ja registrado.';
  END IF;

  IF OLD.state IN ('SIGNED','FAILED') AND NEW.state <> OLD.state THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_TERMINAL: execucao % ja esta em estado terminal %.', OLD.id, OLD.state;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_notify_payment_terms_pending()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_should_notify boolean := false;
  v_msg text;
BEGIN
  IF NEW.requires_financial_approval IS DISTINCT FROM true
     OR NEW.financial_approval_status IS DISTINCT FROM 'pending' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_should_notify := true;
  ELSE
    -- Só notifica quando entra em pending vindo de outro estado
    IF COALESCE(OLD.requires_financial_approval, false) = false
       OR COALESCE(OLD.financial_approval_status, 'not_required') <> 'pending' THEN
      v_should_notify := true;
    END IF;
  END IF;

  IF NOT v_should_notify THEN
    RETURN NEW;
  END IF;

  v_msg := format('Pedido B2B %s aguarda aprovação da condição de pagamento.', COALESCE(NEW.numero,''));

  PERFORM public._notify_role(
    'financeiro'::app_role,
    'b2b_payment_terms_pending',
    'Aprovação financeira pendente',
    v_msg,
    '/comercial/pedidos-b2b'
  );
  PERFORM public._notify_role(
    'administrador'::app_role,
    'b2b_payment_terms_pending',
    'Aprovação financeira pendente',
    v_msg,
    '/comercial/pedidos-b2b'
  );
  PERFORM public._notify_role(
    'gestor_comercial'::app_role,
    'b2b_payment_terms_pending',
    'Aprovação financeira pendente',
    v_msg,
    '/comercial/pedidos-b2b'
  );

  -- Notifica também o criador do pedido, se identificado
  IF NEW.created_by IS NOT NULL THEN
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link, lido)
    VALUES (
      NEW.created_by,
      'b2b_payment_terms_pending',
      'Aprovação financeira pendente',
      v_msg,
      '/comercial/pedidos-b2b',
      false
    );
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_partner_orders_credit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v jsonb;
  v_amount numeric(14,2);
  v_should_check boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('rascunho') THEN v_should_check := true; END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.credit_approved_by IS NOT NULL
       AND NEW.status = 'em_analise_comercial'
       AND OLD.status = 'aguardando_aprovacao_credito'
       AND NEW.total IS NOT DISTINCT FROM OLD.total THEN
      NEW.credit_block_reason := NULL;
      RETURN NEW;
    END IF;

    IF NEW.credit_approved_by IS NOT NULL AND OLD.credit_approved_by IS NULL THEN
      NEW.credit_block_reason := NULL;
      RETURN NEW;
    END IF;

    IF OLD.credit_approved_by IS NOT NULL
       AND NEW.status = 'aprovado'
       AND OLD.status = 'em_analise_comercial'
       AND NEW.total IS NOT DISTINCT FROM OLD.total THEN
      RETURN NEW;
    END IF;

    IF NEW.status IS DISTINCT FROM OLD.status
       AND NEW.status IN ('em_analise_comercial','aprovado') THEN
      v_should_check := true;
    ELSIF (NEW.total IS DISTINCT FROM OLD.total
        OR NEW.final_amount_with_interest IS DISTINCT FROM OLD.final_amount_with_interest)
       AND NEW.status IN ('em_analise_comercial','aprovado','aguardando_aprovacao_credito') THEN
      v_should_check := true;
    END IF;
  END IF;

  IF NOT v_should_check THEN RETURN NEW; END IF;

  -- Serializa a avaliacao de credito por parceiro dentro da transacao corrente.
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_credit:' || NEW.partner_id::text, 0));

  v_amount := ROUND(COALESCE(NEW.final_amount_with_interest, NEW.total, 0), 2);
  v := public.fn_b2b_credit_exposure(NEW.partner_id, v_amount, NEW.id);

  IF (v->>'block_if_overdue')::boolean AND (v->>'tem_vencidos')::boolean THEN
    NEW.status := 'aguardando_aprovacao_credito';
    NEW.credit_block_reason := 'inadimplencia';
    RETURN NEW;
  END IF;

  IF COALESCE((v->>'credit_limit')::numeric,0) > 0
     AND (v->>'exposicao_projetada')::numeric > (v->>'credit_limit')::numeric THEN
    NEW.status := 'aguardando_aprovacao_credito';
    NEW.credit_block_reason := CASE
      WHEN (v->>'credit_limit_action') = 'approval_required' THEN 'limite_excedido'
      ELSE 'limite_excedido_bloqueado'
    END;
  END IF;

  RETURN NEW;
END $function$

