CREATE OR REPLACE FUNCTION public.validate_estoque_entrada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Reservas parciais (têm quantidade_reservada preenchida) seguem normalmente
  IF NEW.quantidade_reservada IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Exigir envase para o lote
  IF NOT EXISTS (SELECT 1 FROM public.envase WHERE lote_id = NEW.lote_id) THEN
    RAISE EXCEPTION 'Não é possível criar entrada no estoque: o lote ainda não possui registro de envase.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Bloquear duplicidade por envase_id (não mais por lote)
  IF NEW.envase_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.estoque_produto
    WHERE envase_id = NEW.envase_id
      AND quantidade_reservada IS NULL
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) THEN
    RAISE EXCEPTION 'Já existe entrada de estoque para este envase.'
      USING ERRCODE = 'unique_violation';
  END IF;

  -- Compat: se a entrada vier sem envase_id, manter a regra antiga de 1 por lote
  IF NEW.envase_id IS NULL AND EXISTS (
    SELECT 1 FROM public.estoque_produto
    WHERE lote_id = NEW.lote_id
      AND envase_id IS NULL
      AND quantidade_reservada IS NULL
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) THEN
    RAISE EXCEPTION 'Já existe uma entrada de estoque agregada para este lote.'
      USING ERRCODE = 'unique_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_estoque_reserva()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status::text = 'reservado' AND (OLD.status IS DISTINCT FROM NEW.status OR OLD.status::text <> 'reservado') THEN
    IF NEW.reservado_para_os_id IS NULL THEN
      RAISE EXCEPTION 'Reserva requer uma OS vinculada.' USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.reservado_para_os_tipo = 'b2b' THEN
      IF NEW.reservado_para_partner_id IS NULL THEN
        RAISE EXCEPTION 'Reserva B2B requer um parceiro vinculado.' USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      IF NEW.reservado_para_cliente_id IS NULL AND NEW.reservado_para_partner_id IS NULL THEN
        RAISE EXCEPTION 'Reserva requer um cliente ou parceiro vinculado.' USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    IF NEW.quantidade_reservada IS NULL OR NEW.quantidade_reservada <= 0 THEN
      RAISE EXCEPTION 'Informe uma quantidade reservada maior que zero.' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.quantidade IS NOT NULL AND NEW.quantidade_reservada > NEW.quantidade THEN
      RAISE EXCEPTION 'Quantidade reservada (%) excede o estoque disponível (%).', NEW.quantidade_reservada, NEW.quantidade
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.reservado_em IS NULL THEN NEW.reservado_em := now(); END IF;
    IF NEW.reservado_por IS NULL THEN NEW.reservado_por := auth.uid(); END IF;
  END IF;

  IF NEW.status::text = 'disponivel' AND OLD.status::text = 'reservado' THEN
    NEW.reservado_para_os_id := NULL;
    NEW.reservado_para_os_tipo := NULL;
    NEW.reservado_para_cliente_id := NULL;
    NEW.reservado_para_partner_id := NULL;
    NEW.reservado_para_partner_order_id := NULL;
    NEW.quantidade_reservada := NULL;
    NEW.reservado_por := NULL;
    NEW.reservado_em := NULL;
    NEW.observacao_reserva := NULL;
  END IF;

  IF NEW.status::text = 'expedido' AND OLD.status::text <> 'expedido' THEN
    IF NEW.expedido_em IS NULL THEN NEW.expedido_em := now(); END IF;
    IF NEW.expedido_por IS NULL THEN NEW.expedido_por := auth.uid(); END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_partner_user_client_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Preenche user_role automaticamente se vazio
  IF NEW.user_role IS NULL THEN
    NEW.user_role := public.get_b2b_user_role_for_partner(NEW.user_id, NEW.partner_id);
  END IF;

  -- Usuário deve pertencer ao parceiro
  IF NOT public.is_valid_b2b_partner_user(NEW.user_id, NEW.partner_id) THEN
    RAISE EXCEPTION 'Usuário % não é um usuário B2B válido do parceiro %', NEW.user_id, NEW.partner_id;
  END IF;

  -- Cliente deve estar vinculado ao parceiro (ativo) em partner_clients
  IF NOT EXISTS (
    SELECT 1 FROM public.partner_clients pc
    WHERE pc.partner_id = NEW.partner_id
      AND pc.cliente_id = NEW.cliente_id
      AND pc.active = true
  ) THEN
    RAISE EXCEPTION 'Cliente % não está vinculado ao parceiro %', NEW.cliente_id, NEW.partner_id;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_responsavel_producao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_ok boolean;
BEGIN
  IF NEW.responsavel_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT user_id INTO v_user_id
  FROM public.profiles
  WHERE id = NEW.responsavel_id;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Responsável inválido: perfil não encontrado'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = v_user_id
      AND role::text IN ('administrador','gestor','operador_onfarm','producao')
  ) INTO v_ok;

  IF NOT v_ok THEN
    RAISE EXCEPTION 'Responsável inválido: perfil sem permissão para produção do laboratório'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_retorno_tecnico_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    has_overlap BOOLEAN;
    visit_duration INTEGER;
BEGIN
    -- Se tem data e consultor, validar sobreposição (independente do tipo de demanda)
    IF NEW.data_prevista_atendimento IS NOT NULL AND NEW.consultor_atribuido IS NOT NULL THEN

        -- Duração padrão de 120 min se não informado
        visit_duration := COALESCE(NEW.duracao_estimada, 120);

        -- Verificar sobreposições
        -- Consideramos que uma visita ocupa o intervalo [data, data + duracao]
        SELECT EXISTS (
            SELECT 1 FROM portal_solicitacoes
            WHERE consultor_atribuido = NEW.consultor_atribuido
            AND id <> NEW.id -- desconsiderar a própria
            AND data_prevista_atendimento IS NOT NULL
            AND status NOT IN ('concluida', 'cancelada')
            AND (
                -- Caso A: Nova visita começa DURANTE uma existente
                (NEW.data_prevista_atendimento >= data_prevista_atendimento AND NEW.data_prevista_atendimento < (data_prevista_atendimento + (COALESCE(duracao_estimada, 120) || ' minutes')::interval))
                OR
                -- Caso B: Visita existente começa DURANTE a nova
                (data_prevista_atendimento >= NEW.data_prevista_atendimento AND data_prevista_atendimento < (NEW.data_prevista_atendimento + (visit_duration || ' minutes')::interval))
            )
        ) INTO has_overlap;

        IF has_overlap THEN
            RAISE EXCEPTION 'CONFLITO_AGENDA: Já existe uma visita agendada para este consultor neste horário ou intervalo.';
        END IF;
    END IF;

    -- Validações específicas para o tipo 'retorno_tecnico'
    IF NEW.tipo_demanda = 'retorno_tecnico' THEN
        -- Validar data obrigatória e no futuro (tolerância de 1h)
        IF NEW.data_prevista_atendimento IS NULL THEN
            RAISE EXCEPTION 'Data prevista é obrigatória para retornos técnicos.';
        END IF;

        IF NEW.data_prevista_atendimento < now() - interval '1 hour' THEN
            RAISE EXCEPTION 'A data do retorno não pode ser no passado.';
        END IF;

        -- Validar descrição/motivo
        IF NEW.descricao IS NULL OR length(trim(NEW.descricao)) < 5 THEN
            RAISE EXCEPTION 'O motivo do retorno deve ser detalhado na descrição.';
        END IF;

        -- Validar consultor
        IF NEW.consultor_atribuido IS NULL THEN
            RAISE EXCEPTION 'Um consultor deve estar atribuído ao retorno.';
        END IF;

        -- Validar duração
        IF NEW.duracao_estimada IS NULL OR NEW.duracao_estimada <= 0 THEN
             RAISE EXCEPTION 'Duração estimada é obrigatória para retornos técnicos.';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_user_access_cliente(_cliente_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id uuid := auth.uid();
    v_is_admin boolean;
    v_is_gestor boolean;
    v_is_adm_sys boolean;
    v_is_financeiro boolean;
    v_is_comercial boolean;
    v_is_producao boolean;
    v_is_aplicador boolean;
    v_is_onfarm boolean;
    v_is_consultor boolean;
    v_is_tecnico boolean;
    v_is_cliente boolean;
    v_is_b2b boolean;
    v_is_b2b_tec boolean;
    v_partner_id uuid;
BEGIN
    IF v_user_id IS NULL OR _cliente_id IS NULL THEN
        RETURN FALSE;
    END IF;

    v_is_admin := COALESCE(has_role(v_user_id, 'administrador'::app_role), false);
    v_is_gestor := COALESCE(has_role(v_user_id, 'gestor'::app_role), false);
    v_is_adm_sys := COALESCE(has_role(v_user_id, 'administrativo'::app_role), false);
    v_is_financeiro := COALESCE(has_role(v_user_id, 'financeiro'::app_role), false);
    v_is_comercial := COALESCE(has_role(v_user_id, 'gestor_comercial'::app_role), false);
    v_is_producao := COALESCE(has_role(v_user_id, 'producao'::app_role), false);
    v_is_aplicador := COALESCE(has_role(v_user_id, 'aplicador'::app_role), false);
    v_is_onfarm := COALESCE(has_role(v_user_id, 'operador_onfarm'::app_role), false);
    v_is_consultor := COALESCE(has_role(v_user_id, 'consultor_tecnico'::app_role), false);
    v_is_tecnico := COALESCE(has_role(v_user_id, 'tecnico_agronomo'::app_role), false);
    v_is_cliente := COALESCE(has_role(v_user_id, 'cliente_produtor'::app_role), false);
    v_is_b2b := COALESCE(has_role(v_user_id, 'parceiro_b2b'::app_role), false);
    v_is_b2b_tec := COALESCE(has_role(v_user_id, 'parceiro_b2b_tecnico'::app_role), false);

    IF v_is_admin OR v_is_gestor OR v_is_adm_sys OR v_is_financeiro
       OR v_is_comercial OR v_is_producao OR v_is_aplicador OR v_is_onfarm THEN
        RETURN TRUE;
    END IF;

    IF v_is_cliente THEN
        RETURN COALESCE(_cliente_id = ANY(get_cliente_ids_for_user(v_user_id)), false);
    END IF;

    -- HARDENING: carteira ativa e vigente é obrigatória para papéis técnicos.
    IF v_is_consultor OR v_is_tecnico THEN
        RETURN COALESCE(
          public.has_active_user_cliente_access(
            v_user_id, _cliente_id, ARRAY['read','execute','manage']
          ), false);
    END IF;

    IF v_is_b2b_tec THEN
        v_partner_id := public.get_user_partner_id();
        RETURN COALESCE((
          EXISTS (
            SELECT 1 FROM public.partner_technician_clients ptc
            WHERE ptc.cliente_id = _cliente_id
              AND ptc.technician_user_id = v_user_id
              AND ptc.partner_id = v_partner_id
              AND ptc.active = true
          )), false);
    END IF;

    IF v_is_b2b THEN
        v_partner_id := public.get_user_partner_id();
        RETURN COALESCE((
          EXISTS (
            SELECT 1 FROM public.partner_technician_clients ptc
            WHERE ptc.cliente_id = _cliente_id
              AND ptc.partner_id = v_partner_id
              AND ptc.active = true
          ) OR EXISTS (
            SELECT 1 FROM public.partner_clients pc
            WHERE pc.cliente_id = _cliente_id
              AND pc.partner_id = v_partner_id
              AND pc.active = true
          )), false);
    END IF;

    RETURN FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_user_access_estoque_embalagem(p_embalagem_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_cli uuid; v_status text; v_entrega uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;
  SELECT cliente_id, status, entrega_id INTO v_cli, v_status, v_entrega
    FROM public.estoque_embalagens WHERE id = p_embalagem_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF public.has_role(v_uid,'administrador'::app_role)
     OR public.has_role(v_uid,'gestor'::app_role)
     OR public.has_role(v_uid,'producao'::app_role)
     OR public.has_role(v_uid,'operador_onfarm'::app_role)
     OR public.has_role(v_uid,'administrativo'::app_role) THEN
    RETURN true;
  END IF;
  IF public.has_role(v_uid,'financeiro'::app_role) THEN
    RETURN v_entrega IS NOT NULL;
  END IF;
  IF public.has_role(v_uid,'consultor_tecnico'::app_role)
     OR public.has_role(v_uid,'tecnico_agronomo'::app_role) THEN
    RETURN v_cli IS NOT NULL AND EXISTS(
      SELECT 1 FROM public.user_clientes WHERE user_id=v_uid AND cliente_id=v_cli);
  END IF;
  IF public.has_role(v_uid,'cliente_produtor'::app_role) THEN
    RETURN v_status='entregue' AND v_cli IS NOT NULL AND EXISTS(
      SELECT 1 FROM public.user_clientes WHERE user_id=v_uid AND cliente_id=v_cli);
  END IF;
  RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.can_user_access_produto_etiqueta(p_etiqueta_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_cliente_id uuid;
  v_gerada_por uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;

  -- Perfis internos com acesso total
  IF public.has_role(v_uid,'administrador'::app_role)
     OR public.has_role(v_uid,'gestor'::app_role)
     OR public.has_role(v_uid,'producao'::app_role)
     OR public.has_role(v_uid,'operador_onfarm'::app_role)
     OR public.has_role(v_uid,'administrativo'::app_role)
     OR public.has_role(v_uid,'financeiro'::app_role)
  THEN
    RETURN true;
  END IF;

  SELECT cliente_id, gerada_por
    INTO v_cliente_id, v_gerada_por
    FROM public.produto_etiquetas
   WHERE id = p_etiqueta_id;

  IF NOT FOUND THEN RETURN false; END IF;

  -- Cliente produtor: apenas etiquetas dos seus clientes
  IF public.has_role(v_uid,'cliente_produtor'::app_role) THEN
    IF v_cliente_id IS NULL THEN RETURN false; END IF;
    RETURN EXISTS (
      SELECT 1 FROM public.user_clientes uc
       WHERE uc.user_id = v_uid AND uc.cliente_id = v_cliente_id
    );
  END IF;

  -- Consultor/técnico: regra conservadora — apenas se gerada por ele
  -- ou se estiver vinculado ao cliente em user_clientes
  IF public.has_role(v_uid,'consultor_tecnico'::app_role)
     OR public.has_role(v_uid,'tecnico_agronomo'::app_role)
  THEN
    IF v_gerada_por = v_uid THEN RETURN true; END IF;
    IF v_cliente_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.user_clientes uc
       WHERE uc.user_id = v_uid AND uc.cliente_id = v_cliente_id
    ) THEN
      RETURN true;
    END IF;
    RETURN false;
  END IF;

  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_micro_profile_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
  v_alvos int;
  v_fontes int;
  v_old_status text := CASE WHEN TG_OP = 'UPDATE' THEN OLD.status_validacao ELSE NULL END;
BEGIN
  IF NEW.status_validacao = 'aprovado'
     AND (TG_OP = 'INSERT' OR COALESCE(v_old_status, '') <> 'aprovado') THEN

    IF COALESCE(btrim(NEW.resumo_curto), '') = '' THEN RAISE EXCEPTION 'approval_missing_resumo_curto'; END IF;
    IF COALESCE(btrim(NEW.explicacao_tecnica), '') = '' THEN RAISE EXCEPTION 'approval_missing_explicacao_tecnica'; END IF;
    IF COALESCE(btrim(NEW.explicacao_produtor), '') = '' THEN RAISE EXCEPTION 'approval_missing_explicacao_produtor'; END IF;
    IF COALESCE(btrim(NEW.mecanismo_acao), '') = '' THEN RAISE EXCEPTION 'approval_missing_mecanismo_acao'; END IF;
    IF COALESCE(btrim(NEW.beneficios_agronomicos), '') = '' THEN RAISE EXCEPTION 'approval_missing_beneficios_agronomicos'; END IF;
    IF COALESCE(btrim(NEW.observacoes_regulatorias), '') = '' THEN RAISE EXCEPTION 'approval_missing_observacoes_regulatorias'; END IF;

    SELECT count(*) INTO v_alvos FROM public.microorganism_targets
      WHERE microrganismo_id = NEW.microrganismo_id AND ativo = true;
    IF v_alvos = 0 THEN RAISE EXCEPTION 'approval_missing_alvos'; END IF;

    IF v_uid IS NOT NULL THEN
      SELECT (public.has_role(v_uid, 'administrador'::app_role)
           OR public.has_role(v_uid, 'gestor'::app_role)) INTO v_is_admin;
    END IF;

    IF NOT v_is_admin THEN
      SELECT count(*) INTO v_fontes FROM public.catalog_technical_sources
        WHERE (entidade_tipo = 'ficha_microrganismo' AND entidade_id = NEW.id)
           OR (entidade_tipo = 'microrganismo' AND entidade_id = NEW.microrganismo_id);
      IF v_fontes = 0 THEN RAISE EXCEPTION 'approval_missing_fontes'; END IF;
    END IF;

    IF NEW.validado_por IS NULL THEN NEW.validado_por := v_uid; END IF;
    IF NEW.validado_em IS NULL THEN NEW.validado_em := now(); END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.updated_by := COALESCE(v_uid, NEW.updated_by);
    NEW.updated_at := now();
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_product_profile_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
  v_alvos int;
  v_fontes int;
  v_comp int;
  v_old_status text := CASE WHEN TG_OP = 'UPDATE' THEN OLD.status_validacao ELSE NULL END;
BEGIN
  IF NEW.status_validacao = 'aprovado'
     AND (TG_OP = 'INSERT' OR COALESCE(v_old_status, '') <> 'aprovado') THEN

    IF COALESCE(btrim(NEW.resumo_curto), '') = '' THEN RAISE EXCEPTION 'approval_missing_resumo_curto'; END IF;
    IF COALESCE(btrim(NEW.explicacao_tecnica), '') = '' THEN RAISE EXCEPTION 'approval_missing_explicacao_tecnica'; END IF;
    IF COALESCE(btrim(NEW.explicacao_produtor), '') = '' THEN RAISE EXCEPTION 'approval_missing_explicacao_produtor'; END IF;
    IF COALESCE(btrim(NEW.beneficio_combinado), '') = '' THEN RAISE EXCEPTION 'approval_missing_beneficio_combinado'; END IF;
    IF COALESCE(btrim(NEW.observacoes_regulatorias), '') = ''
       AND COALESCE(btrim(NEW.cuidados_aplicacao), '') = '' THEN
      RAISE EXCEPTION 'approval_missing_observacoes_ou_cuidados';
    END IF;

    SELECT count(*) INTO v_comp FROM public.formulacoes WHERE produto_id = NEW.produto_id;
    IF v_comp = 0 THEN RAISE EXCEPTION 'approval_missing_composicao'; END IF;

    SELECT count(*) INTO v_alvos FROM public.product_target_recommendations
      WHERE produto_id = NEW.produto_id AND ativo = true;
    IF v_alvos = 0 THEN RAISE EXCEPTION 'approval_missing_alvos'; END IF;

    IF v_uid IS NOT NULL THEN
      SELECT (public.has_role(v_uid, 'administrador'::app_role)
           OR public.has_role(v_uid, 'gestor'::app_role)) INTO v_is_admin;
    END IF;

    IF NOT v_is_admin THEN
      SELECT count(*) INTO v_fontes FROM public.catalog_technical_sources
        WHERE (entidade_tipo = 'ficha_produto' AND entidade_id = NEW.id)
           OR (entidade_tipo = 'produto' AND entidade_id = NEW.produto_id);
      IF v_fontes = 0 THEN RAISE EXCEPTION 'approval_missing_fontes'; END IF;
    END IF;

    IF NEW.validado_por IS NULL THEN NEW.validado_por := v_uid; END IF;
    IF NEW.validado_em IS NULL THEN NEW.validado_em := now(); END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.updated_by := COALESCE(v_uid, NEW.updated_by);
    NEW.updated_at := now();
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_cockpit_assert_operador_origem(p_origem text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_origem text := public.fn_cockpit_norm_origem(p_origem);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'COCKPIT_UNAUTHENTICATED'; END IF;

  IF public.has_role(v_uid, 'administrador'::app_role)
     OR public.has_role(v_uid, 'gestor'::app_role) THEN
    RETURN v_origem;
  END IF;

  -- produção: fluxo industrial (manual/onfarm/b2b), sem privilégio de override
  IF public.has_role(v_uid, 'producao'::app_role) THEN
    RETURN v_origem;
  END IF;

  -- operador on-farm: alçada restrita à própria origem
  IF public.has_role(v_uid, 'operador_onfarm'::app_role) THEN
    IF v_origem <> 'onfarm' THEN
      RAISE EXCEPTION 'COCKPIT_FORBIDDEN_ORIGEM';
    END IF;
    RETURN v_origem;
  END IF;

  RAISE EXCEPTION 'COCKPIT_FORBIDDEN';
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_b2b_receivable_secure(p_partner_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;

  IF auth.uid() IS NULL THEN
    IF pg_trigger_depth()=0 THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  ELSIF NOT (public.b2b_phase1_order_visible(p_partner_order_id) OR EXISTS (
    SELECT 1 FROM public.partner_orders po WHERE po.id=p_partner_order_id
      AND platform_private.c2p1_settings_allowed(po.partner_id,true))) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF NOT (pg_trigger_depth() > 0 or public.has_role(auth.uid(), 'administrador'::public.app_role)
      or public.has_role(auth.uid(), 'gestor'::public.app_role)
      or public.has_role(auth.uid(), 'financeiro'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
 IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_partner_order_id AND internal_origin_snapshot IS NOT NULL) THEN RAISE EXCEPTION 'B2B_INTERNAL_DOWNSTREAM_UNVERIFIED' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_partner_order_id AND c2_external_origin_snapshot->>'contract'='C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1') THEN RAISE EXCEPTION 'C2_ACCOUNTING_PENDING' USING ERRCODE='42501'; END IF;
  IF p_partner_order_id IS NULL THEN
    RAISE EXCEPTION 'partner_order_id_required' USING ERRCODE='P0001';
  END IF;

  -- Canonical row-before-receipt order, matching approval and its billing trigger.
  PERFORM 1 FROM public.partner_orders WHERE id=p_partner_order_id FOR UPDATE;

  -- Serializa concorrencia real (clique duplo / chamadas simultaneas).
  -- Chave unica bigint: assinatura pg_advisory_xact_lock(bigint).
  PERFORM pg_advisory_xact_lock(
    hashtextextended('b2b_receivable:' || p_partner_order_id::text, 0)
  );

  IF NOT public.fn_b2b_order_priceable(p_partner_order_id) THEN
    RAISE EXCEPTION 'order_not_priceable_quote_required' USING ERRCODE='P0001';
  END IF;

  RETURN public.generate_b2b_receivable_secure_impl(p_partner_order_id);
END $function$

CREATE OR REPLACE FUNCTION public.generate_b2b_receivable_secure_impl(p_partner_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_order record;
  v_partner record;
  v_settings record;
  v_terms record;
  v_receivable_id uuid;
  v_category_id uuid;
  v_payment_method_id uuid;
  v_existing uuid;
  v_sch record;
  v_ari_id uuid;
  v_installments_json jsonb := '[]'::jsonb;
  v_system_call boolean := (v_uid IS NULL);
  v_gate jsonb;
  v_fiscal jsonb;
  v_uf text;
  v_org uuid;
  v_org_count integer; -- b2b_f1_financial_tenant
BEGIN
  IF NOT v_system_call THEN
    IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'financeiro') OR has_role(v_uid,'gestor') OR has_role(v_uid,'gestor_comercial')) THEN
      INSERT INTO public.partner_order_audit_logs(order_id, usuario_id, acao, dados_novos)
        VALUES (p_partner_order_id, v_uid, 'financeiro_permissao_negada', jsonb_build_object('motivo','sem permissão'));
      RAISE EXCEPTION 'Sem permissão para gerar cobrança B2B';
    END IF;
  END IF;

  SELECT * INTO v_order FROM public.partner_orders WHERE id = p_partner_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado'; END IF;

  -- Deterministic partner ownership, never caller-supplied organization.
  SELECT count(*), min(o.id::text)::uuid INTO v_org_count,v_org
    FROM public.organizations o WHERE o.partner_account_id=v_order.partner_id;
  -- c2_ord_owner_tenant: cliente comercial sem tenant próprio fatura no tenant dono.
  IF v_org_count = 0 THEN
    SELECT count(*), min(o.id::text)::uuid INTO v_org_count, v_org
      FROM public.partner_accounts pa JOIN public.organizations o ON o.id = pa.commercial_owner_organization_id
     WHERE pa.id = v_order.partner_id AND pa.ativo IS TRUE AND pa.deleted_at IS NULL
       AND o.ativo IS TRUE AND o.status = 'ativa';
  END IF;
  IF v_org_count <> 1 OR v_org IS NULL THEN
    RAISE EXCEPTION 'B2B_FINANCIAL_TENANT_AMBIGUOUS' USING ERRCODE='42501';
  END IF;
  IF v_uid IS NOT NULL THEN
    -- c2_ord_internal_scope: emissor interno é limitado por h15 = tenant do título (abaixo);
    -- quem tem papel B2B externo continua passando pelo assert canônico.
    IF public.has_role(v_uid,'parceiro_b2b'::app_role) OR public.has_role(v_uid,'parceiro_b2b_tecnico'::app_role) THEN
      PERFORM platform_private.assert_b2b_partner_scope(v_uid,v_order.partner_id);
    END IF;
    IF NOT public.is_platform_superadmin(v_uid) AND public.h15_actor_organization() IS DISTINCT FROM v_org THEN
      RAISE EXCEPTION 'B2B_FINANCIAL_TENANT_MISMATCH' USING ERRCODE='42501';
    END IF;
  END IF;

  IF v_order.c2_external_origin_snapshot IS NOT NULL THEN
    PERFORM platform_private.c2_external_origin_assert(v_order.c2_external_origin_snapshot,v_order.partner_id,v_order.cliente_id);
    IF v_org::text IS DISTINCT FROM v_order.c2_external_origin_snapshot->>'creditor_organization_id' THEN RAISE EXCEPTION 'C2_EXTERNAL_CREDITOR_DRIFT' USING ERRCODE='42501'; END IF;
  END IF;

  -- GATE Fase C: elegibilidade server-side
  v_gate := public.fn_b2b_order_billing_eligibility(p_partner_order_id);
  IF NOT (v_gate->>'eligible')::boolean THEN
    INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
      VALUES (p_partner_order_id, v_order.partner_id, v_uid, 'financeiro_bloqueado_gate', v_gate);
    RAISE EXCEPTION 'billing_not_eligible:%', v_gate->>'reason_code';
  END IF;

  -- H6C-001: condicao canonica vinculada ao pedido (nunca a mais recente).
  SELECT * INTO v_terms FROM public.partner_order_payment_terms
    WHERE id = NULLIF(v_gate->>'payment_terms_id','')::uuid
      AND partner_order_id = p_partner_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'payment_terms_not_canonical'; END IF;

  SELECT receivable_id INTO v_existing FROM public.partner_order_financial_links WHERE partner_order_id = p_partner_order_id;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
      VALUES (p_partner_order_id, v_order.partner_id, v_uid, 'financeiro_duplicidade_bloqueada', jsonb_build_object('receivable_id', v_existing));
    RETURN jsonb_build_object('receivable_id', v_existing, 'partner_order_id', p_partner_order_id, 'duplicado', true);
  END IF;

  SELECT * INTO v_partner FROM public.partner_accounts WHERE id = v_order.partner_id;
  SELECT * INTO v_settings FROM public.partner_financial_settings WHERE partner_id = v_order.partner_id;
  IF NOT FOUND THEN
    -- c2_ord_p1_no_provision: only the existing P1 CAS RPC creates settings.
    RAISE EXCEPTION 'B2B_FINANCIAL_SETTINGS_NOT_CONFIGURED' USING ERRCODE='P0001';
  END IF;

  -- External manual billing must honor configured delivery prerequisite too.
  IF v_order.c2_external_origin_snapshot IS NOT NULL AND v_settings.billing_trigger='na_entrega' AND v_order.status IS DISTINCT FROM 'entregue' THEN
    RAISE EXCEPTION 'C2_EXTERNAL_DELIVERY_REQUIRED' USING ERRCODE='42501';
  END IF;

  v_uf := to_jsonb(v_partner) ->> 'uf';

  -- Derivação fiscal (fail-closed; nunca NOT_REQUIRED silencioso)
  v_fiscal := public.fn_fiscal_requirement_resolve(
    'b2b_partner', 'venda_mercadoria', v_uf, 'partner_order', p_partner_order_id, CURRENT_DATE);

  -- c2_ord_strict_refs: financial_categories/payment_methods são catálogos globais por desenho (sem organization_id, RLS is_financial_staff; sem DDL de tenant
  -- no schema canônico); resolução estrita, sem fallback de tipo/inativo, falha explícita.
  SELECT id INTO v_category_id FROM public.financial_categories
   WHERE upper(btrim(type)) = 'RECEITA' AND active IS TRUE
   ORDER BY created_at ASC, id ASC LIMIT 1;
  IF v_category_id IS NULL THEN
    RAISE EXCEPTION 'B2B_REVENUE_CATEGORY_NOT_CONFIGURED' USING ERRCODE='P0001';
  END IF;
  IF NULLIF(btrim(COALESCE(v_settings.default_payment_method,'')),'') IS NULL THEN
    RAISE EXCEPTION 'B2B_PAYMENT_METHOD_NOT_CONFIGURED' USING ERRCODE='P0001';
  END IF;
  IF (SELECT count(*) FROM public.payment_methods pm
       WHERE pm.active IS TRUE AND lower(btrim(pm.name)) = lower(btrim(v_settings.default_payment_method))) <> 1 THEN
    RAISE EXCEPTION 'B2B_PAYMENT_METHOD_NOT_CONFIGURED' USING ERRCODE='P0001';
  END IF;
  SELECT pm.id INTO v_payment_method_id FROM public.payment_methods pm
   WHERE pm.active IS TRUE AND lower(btrim(pm.name)) = lower(btrim(v_settings.default_payment_method));
  IF v_partner.client_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.clientes cl WHERE cl.id = v_partner.client_id AND cl.organization_id = v_org) THEN
    RAISE EXCEPTION 'B2B_CUSTOMER_TENANT_MISMATCH' USING ERRCODE='42501';
  END IF;

  INSERT INTO public.accounts_receivable(
    organization_id, origin_type, origin_id, customer_id, partner_id, description,
    category_id, total_amount, issue_date, first_due_date, installment_count,
    status, fiscal_invoice_required, fiscal_invoice_status,
    fiscal_requirement_source, fiscal_policy_id, fiscal_exemption_id,
    payment_method_id, notes, created_by
  ) VALUES (
    v_org, 'B2B_ORDER', p_partner_order_id,
    NULLIF(v_partner.client_id, NULL), v_order.partner_id,
    format('Pedido B2B %s - %s', v_order.numero, COALESCE(v_partner.nome_fantasia, v_partner.razao_social)),
    v_category_id, v_terms.final_amount, CURRENT_DATE, v_terms.first_due_date, v_terms.installment_count,
    'OPEN',
    (v_fiscal->>'required')::boolean,
    v_fiscal->>'status',
    v_fiscal->>'source',
    NULLIF(v_fiscal->>'policy_id','')::uuid,
    NULLIF(v_fiscal->>'exemption_id','')::uuid,
    v_payment_method_id,
    format(E'Condição: %s (%s)\nDesconto: %s%%  Juros: %s%% a.m. x %s meses\nTabela: %s  Líquido: %s  Final: %s\nFiscal: %s (%s)',
           v_terms.plan_name_snapshot, v_terms.plan_code_snapshot,
           v_terms.discount_percent_snapshot, v_terms.monthly_interest_percent_snapshot, v_terms.months_count_snapshot,
           v_terms.table_amount, v_terms.net_amount_after_discount, v_terms.final_amount,
           v_fiscal->>'status', v_fiscal->>'source'),
    COALESCE(v_uid, v_order.created_by)
  ) RETURNING id INTO v_receivable_id;

  -- b2b_f1_fresh_title: no deletion; formal financial history protection preserved.

  FOR v_sch IN
    SELECT * FROM public.partner_order_payment_schedule
     WHERE partner_order_id = p_partner_order_id AND payment_terms_id = v_terms.id
     ORDER BY installment_number
  LOOP
    -- b2b_f1_reuse_installments: generic title trigger already created them.
    IF (SELECT count(*) FROM public.accounts_receivable_installments
         WHERE receivable_id=v_receivable_id AND installment_number=v_sch.installment_number
           AND organization_id=v_org) <> 1 THEN
      RAISE EXCEPTION 'B2B_INSTALLMENT_CARDINALITY_INVALID' USING ERRCODE='23514';
    END IF;
    UPDATE public.accounts_receivable_installments
       SET due_date=v_sch.due_date, original_amount=v_sch.amount,
           interest_amount=COALESCE(v_sch.interest_amount,0), net_amount=v_sch.amount
     WHERE receivable_id=v_receivable_id AND installment_number=v_sch.installment_number
       AND organization_id=v_org
     RETURNING id INTO v_ari_id;

    UPDATE public.partner_order_payment_schedule
       SET status = 'generated', receivable_installment_id = v_ari_id
     WHERE id = v_sch.id;

    v_installments_json := v_installments_json || jsonb_build_array(jsonb_build_object(
      'installment_number', v_sch.installment_number,
      'due_date', v_sch.due_date,
      'amount', v_sch.amount
    ));
  END LOOP;

  INSERT INTO public.partner_order_financial_links(
    partner_order_id, partner_id, receivable_id, financial_status, billing_trigger, created_by
  ) VALUES (
    p_partner_order_id, v_order.partner_id, v_receivable_id, 'gerado', v_settings.billing_trigger, v_uid
  );

  UPDATE public.partner_orders SET
    financial_status = 'gerado',
    receivable_generated = true,
    receivable_generated_at = now(),
    receivable_generated_by = v_uid,
    payment_due_date = v_terms.first_due_date,
    payment_method = COALESCE(v_settings.default_payment_method,'pix')
  WHERE id = p_partner_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (p_partner_order_id, v_order.partner_id, v_uid, 'financeiro_gerado_com_plano',
    jsonb_build_object(
      'receivable_id', v_receivable_id,
      'plan_code', v_terms.plan_code_snapshot,
      'plan_name', v_terms.plan_name_snapshot,
      'table_amount', v_terms.table_amount,
      'discount_amount', v_terms.discount_amount,
      'net_amount', v_terms.net_amount_after_discount,
      'interest_amount', v_terms.financial_interest_amount,
      'final_amount', v_terms.final_amount,
      'first_due_date', v_terms.first_due_date,
      'installment_count', v_terms.installment_count,
      'fiscal', v_fiscal,
      'gate', v_gate,
      'installments', v_installments_json
    ));

  RETURN jsonb_build_object(
    'receivable_id', v_receivable_id,
    'partner_order_id', p_partner_order_id,
    'valor', v_terms.final_amount,
    'vencimento', v_terms.first_due_date,
    'installment_count', v_terms.installment_count,
    'fiscal_invoice_required', (v_fiscal->>'required')::boolean,
    'fiscal_invoice_status', v_fiscal->>'status',
    'fiscal_requirement_source', v_fiscal->>'source',
    'status', 'OPEN'
  );
END 
$function$

CREATE OR REPLACE FUNCTION public.rpc_b2b_financial_kpis(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_partner_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_from date := COALESCE(p_from, date_trunc('month', CURRENT_DATE)::date);
  v_to date := COALESCE(p_to, CURRENT_DATE);
  v_result jsonb;
BEGIN
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'financeiro') OR has_role(v_uid,'gestor') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'Sem permissão';
  END IF;

  WITH ar AS (
    SELECT a.*, i.due_date, i.original_amount, i.received_amount, i.status AS inst_status
    FROM public.accounts_receivable a
    JOIN public.accounts_receivable_installments i ON i.receivable_id = a.id
    WHERE a.origin_type='B2B_ORDER'
      AND a.created_at::date BETWEEN v_from AND v_to
      AND (p_partner_id IS NULL OR a.partner_id = p_partner_id)
  )
  SELECT jsonb_build_object(
    'total_a_receber', COALESCE(SUM(CASE WHEN inst_status IN ('OPEN','PARTIAL','OVERDUE') THEN original_amount - COALESCE(received_amount,0) END),0),
    'total_recebido', COALESCE(SUM(received_amount),0),
    'total_vencido', COALESCE(SUM(CASE WHEN inst_status='OVERDUE' OR (inst_status IN ('OPEN','PARTIAL') AND due_date < CURRENT_DATE) THEN original_amount - COALESCE(received_amount,0) END),0),
    'total_em_aberto', COALESCE(SUM(CASE WHEN inst_status IN ('OPEN','PARTIAL') THEN original_amount - COALESCE(received_amount,0) END),0),
    'ticket_medio', COALESCE(AVG(total_amount),0),
    'vencendo_7d', COALESCE(SUM(CASE WHEN inst_status IN ('OPEN','PARTIAL') AND due_date BETWEEN CURRENT_DATE AND CURRENT_DATE+7 THEN original_amount - COALESCE(received_amount,0) END),0)
  ) INTO v_result FROM ar;

  v_result := v_result || jsonb_build_object(
    'pedidos_entregues_sem_cobranca', (
      SELECT COUNT(*) FROM public.partner_orders po
      WHERE po.status='entregue' AND po.receivable_generated=false
        AND (p_partner_id IS NULL OR po.partner_id = p_partner_id)
    ),
    'parceiros_inadimplentes', (
      SELECT COUNT(DISTINCT partner_id) FROM public.accounts_receivable a
      JOIN public.accounts_receivable_installments i ON i.receivable_id=a.id
      WHERE a.origin_type='B2B_ORDER' AND (i.status='OVERDUE' OR (i.status IN ('OPEN','PARTIAL') AND i.due_date < CURRENT_DATE))
    )
  );

  RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_b2b_governance_kpis()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total_concedido numeric := 0;
  v_total_utilizado numeric := 0;
  v_total_disponivel numeric := 0;
  v_bloqueados int := 0;
  v_vencidos numeric := 0;
  v_recebido_mes numeric := 0;
  v_inad_pct numeric := 0;
  v_receita numeric := 0;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador'::public.app_role)
      or public.has_role(auth.uid(), 'gestor'::public.app_role)
      or public.has_role(auth.uid(), 'financeiro'::public.app_role)
      or public.has_role(auth.uid(), 'gestor_comercial'::public.app_role)
      or public.has_role(auth.uid(), 'administrativo'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(SUM(credit_limit),0) INTO v_total_concedido
    FROM public.partner_financial_settings WHERE active;

  SELECT COALESCE(SUM((ari.original_amount - ari.received_amount)),0) INTO v_total_utilizado
    FROM public.accounts_receivable ar
    JOIN public.accounts_receivable_installments ari ON ari.receivable_id = ar.id
   WHERE ar.origin_type = 'B2B_ORDER' AND ar.status <> 'CANCELED'
     AND ari.status IN ('OPEN','PARTIAL','OVERDUE');

  v_total_disponivel := GREATEST(v_total_concedido - v_total_utilizado, 0);

  SELECT COUNT(DISTINCT partner_id) INTO v_bloqueados
    FROM public.partner_orders WHERE status = 'aguardando_aprovacao_credito';

  SELECT COALESCE(SUM(ari.original_amount - ari.received_amount),0) INTO v_vencidos
    FROM public.accounts_receivable ar
    JOIN public.accounts_receivable_installments ari ON ari.receivable_id = ar.id
   WHERE ar.origin_type = 'B2B_ORDER' AND ar.status <> 'CANCELED'
     AND ari.status IN ('OPEN','PARTIAL','OVERDUE') AND ari.due_date < current_date;

  SELECT COALESCE(SUM(rp.amount_received),0) INTO v_recebido_mes
    FROM public.receivable_payments rp
    JOIN public.accounts_receivable_installments ari ON ari.id = rp.installment_id
    JOIN public.accounts_receivable ar ON ar.id = ari.receivable_id
   WHERE ar.origin_type = 'B2B_ORDER'
     AND date_trunc('month', rp.payment_date) = date_trunc('month', current_date);

  SELECT COALESCE(SUM(total),0) INTO v_receita
    FROM public.partner_orders
   WHERE status IN ('entregue','faturado')
     AND date_trunc('month', created_at) = date_trunc('month', current_date);

  v_inad_pct := CASE WHEN v_total_utilizado > 0
                     THEN ROUND((v_vencidos / v_total_utilizado) * 100, 2)
                     ELSE 0 END;

  RETURN jsonb_build_object(
    'credito_total_concedido', v_total_concedido,
    'credito_utilizado', v_total_utilizado,
    'credito_disponivel', v_total_disponivel,
    'parceiros_bloqueados', v_bloqueados,
    'titulos_vencidos', v_vencidos,
    'recebimentos_mes', v_recebido_mes,
    'inadimplencia_pct', v_inad_pct,
    'receita_b2b_mes', v_receita
  );
END;$function$

CREATE OR REPLACE FUNCTION public.visitas_campo_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Initial contract: a new row always starts at version 1.
    IF NEW.versao IS DISTINCT FROM 1 THEN
      RAISE EXCEPTION 'versao_inicial_invalida' USING ERRCODE = 'PT409';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.registro_consultor_id IS DISTINCT FROM OLD.registro_consultor_id THEN
    RAISE EXCEPTION 'campo_imutavel_registro_consultor_id' USING ERRCODE = '42501';
  END IF;
  IF NEW.cliente_id IS DISTINCT FROM OLD.cliente_id THEN
    RAISE EXCEPTION 'campo_imutavel_cliente_id' USING ERRCODE = '42501';
  END IF;
  IF NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'campo_imutavel_created_by' USING ERRCODE = '42501';
  END IF;
  IF OLD.client_uuid IS NOT NULL AND NEW.client_uuid IS DISTINCT FROM OLD.client_uuid THEN
    RAISE EXCEPTION 'campo_imutavel_client_uuid' USING ERRCODE = '42501';
  END IF;
  -- Strict +1: no NULL, no jump, no repeat, no regression (applies to every writer).
  IF OLD.versao IS NULL OR NEW.versao IS NULL OR NEW.versao <> OLD.versao + 1 THEN
    RAISE EXCEPTION 'versao_deve_incrementar' USING ERRCODE = 'PT409';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_entrega_comprovante_exigir_arquivo_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF NEW.arquivo_path IS NULL THEN
    IF NEW.assinatura_tipo = 'fisica_anexada' THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'O comprovante físico exige um arquivo anexado.';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM storage.objects AS o
    WHERE o.bucket_id = 'entrega-documentos'
      AND o.name = NEW.arquivo_path
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'Arquivo do comprovante não encontrado ou sem acesso no armazenamento.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_entrega_assinatura_exigir_imagem_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF NEW.assinatura_tipo='digital_tela' AND NEW.assinatura_digital_png_path IS NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='A assinatura digital exige uma imagem armazenada.';
 END IF;
 IF NEW.assinatura_digital_png_path IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM storage.objects o
  WHERE o.bucket_id='entrega-documentos' AND o.name=NEW.assinatura_digital_png_path
 ) THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Imagem da assinatura não encontrada ou sem acesso no armazenamento.';
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_entrega_comprovante_preservar_encerrado_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
 v_operacionais text[]:=ARRAY['updated_at','metadata','qr_code_path','qr_code_generated_at','validation_public_enabled','validation_expires_at','validation_url'];
 v_campo text;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.status='confirmado' OR OLD.metadata ? 'comprovante_snapshot_v1' THEN
   RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Comprovante encerrado não pode ser excluído.';
  END IF;
  RETURN OLD;
 END IF;
 IF OLD.status='confirmado' AND
   (to_jsonb(NEW)-v_operacionais) IS DISTINCT FROM (to_jsonb(OLD)-v_operacionais) THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Dados do comprovante confirmado não podem ser alterados.';
 END IF;
 IF OLD.metadata ? 'comprovante_snapshot_v1' THEN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.entrega_id IS DISTINCT FROM OLD.entrega_id THEN
   RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Vínculo do comprovante congelado não pode ser alterado.';
  END IF;
  FOREACH v_campo IN ARRAY ARRAY['comprovante_snapshot_v1','comprovante_snapshot_hash','comprovante_numero'] LOOP
   IF NEW.metadata->v_campo IS DISTINCT FROM OLD.metadata->v_campo THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Conteúdo do comprovante congelado não pode ser alterado.';
   END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_fiscal_audit_base_reduction()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid;
  v_old jsonb := coalesce(CASE WHEN TG_OP = 'UPDATE' THEN OLD.tax_input_snapshot END, '{}'::jsonb);
  v_new jsonb := coalesce(NEW.tax_input_snapshot, '{}'::jsonb);
  v_snap jsonb := coalesce(NEW.tax_snapshot, '{}'::jsonb);
  v_taxes jsonb;
  v_kind text;
  v_oldpct jsonb;
  v_newpct jsonb;
  v_tax jsonb;
BEGIN
  BEGIN v_actor := auth.uid(); EXCEPTION WHEN OTHERS THEN v_actor := NULL; END;

  v_taxes := v_snap->'taxes';
  IF v_taxes IS NULL OR jsonb_typeof(v_taxes) <> 'object' THEN
    v_taxes := '{}'::jsonb;
  END IF;

  -- Materializacao do calculo: registra a reducao efetivamente aplicada, com a
  -- regra, a versao e o fundamento legal vindos do snapshot REAL.
  IF TG_OP = 'UPDATE' AND NEW.tax_snapshot IS DISTINCT FROM OLD.tax_snapshot THEN
    FOR v_kind IN SELECT jsonb_object_keys(v_taxes) LOOP
      v_tax := coalesce(v_taxes -> v_kind, '{}'::jsonb);
      CONTINUE WHEN coalesce((v_tax->>'baseReductionPct')::numeric, 0) = 0;
      INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, old_values, new_values)
      VALUES (
        'fiscal_invoice_items', NEW.id, 'BASE_REDUCTION_APPLIED', v_actor,
        jsonb_build_object('taxKind', v_kind,
          'baseReductionPct', (coalesce(OLD.tax_snapshot,'{}'::jsonb)->'taxes'->v_kind->>'baseReductionPct')),
        jsonb_build_object(
          'taxKind', v_kind,
          'baseReductionPct', v_tax->>'baseReductionPct',
          'reason', coalesce(v_tax->>'baseReductionReason', v_new -> v_kind ->> 'baseReductionReason'),
          'fiscalInvoiceId', NEW.fiscal_invoice_id,
          'itemId', NEW.id,
          'changedAt', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SSZ'),
          'appliedBy', v_tax->>'baseReductionAppliedBy',
          'appliedAt', v_tax->>'baseReductionAppliedAt',
          'ruleId', v_tax->>'ruleId',
          'ruleKey', v_tax->>'ruleKey',
          'ruleVersion', v_tax->>'ruleVersion',
          'legalBasis', v_tax->>'legalBasis',
          'legalVersion', v_tax->>'legalVersion',
          'baseReductionMode', v_tax->>'baseReductionMode',
          'baseReductionSource', v_tax->>'baseReductionSource'));
    END LOOP;
  END IF;

  IF v_old = v_new THEN RETURN NEW; END IF;

  FOR v_kind IN
    SELECT DISTINCT k FROM (
      SELECT jsonb_object_keys(v_old) AS k
      UNION SELECT jsonb_object_keys(v_new)
    ) s
  LOOP
    v_oldpct := v_old -> v_kind -> 'baseReductionPct';
    v_newpct := v_new -> v_kind -> 'baseReductionPct';
    CONTINUE WHEN v_oldpct IS NOT DISTINCT FROM v_newpct;

    v_tax := coalesce(v_taxes -> v_kind, '{}'::jsonb);

    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, old_values, new_values)
    VALUES (
      'fiscal_invoice_items', NEW.id, 'BASE_REDUCTION_CHANGE', v_actor,
      jsonb_build_object(
        'taxKind', v_kind,
        'baseReductionPct', v_oldpct,
        'reason', v_old -> v_kind ->> 'baseReductionReason'),
      jsonb_build_object(
        'taxKind', v_kind,
        'baseReductionPct', v_newpct,
        'reason', v_new -> v_kind ->> 'baseReductionReason',
        'fiscalInvoiceId', NEW.fiscal_invoice_id,
        'itemId', NEW.id,
        'changedAt', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SSZ'),
        'ruleId', v_tax->>'ruleId',
        'ruleKey', v_tax->>'ruleKey',
        'ruleVersion', v_tax->>'ruleVersion',
        'legalBasis', v_tax->>'legalBasis',
        'legalVersion', v_tax->>'legalVersion',
        'baseReductionMode', v_tax->>'baseReductionMode'
      )
    );
  END LOOP;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.h15_active_company()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r uuid; n integer;
BEGIN
 PERFORM public.h15_require_staff();
 SELECT count(*),min(id::text)::uuid INTO n,r FROM public.company_fiscal_settings WHERE organization_id=public.h15_actor_organization() AND is_active;
 IF n<>1 THEN RAISE EXCEPTION 'H15_ACTIVE_COMPANY_AMBIGUOUS' USING ERRCODE='42501'; END IF;
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.h15_invoice_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.company_fiscal_settings; creator_org uuid; k text; expected text; actual text;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.company_settings_id IS DISTINCT FROM OLD.company_settings_id OR NEW.created_by IS DISTINCT FROM OLD.created_by) THEN
 RAISE EXCEPTION 'H15_INVOICE_OWNERSHIP_IMMUTABLE' USING ERRCODE='23514'; END IF;
 SELECT * INTO c FROM public.company_fiscal_settings WHERE id=NEW.company_settings_id;
 SELECT organization_id INTO creator_org FROM public.profiles WHERE user_id=NEW.created_by;
 IF c.id IS NULL OR creator_org IS DISTINCT FROM c.organization_id THEN RAISE EXCEPTION 'H15_CREATOR_ORGANIZATION_MISMATCH' USING ERRCODE='23514'; END IF;
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' THEN
 PERFORM public.h15_require_company(c.id);
 IF TG_OP='INSERT' AND NEW.created_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'H15_CREATOR_FORGED' USING ERRCODE='42501'; END IF;
 END IF;
 IF NEW.company_cnpj IS NOT NULL AND regexp_replace(NEW.company_cnpj,'[^0-9]','','g') IS DISTINCT FROM regexp_replace(c.cnpj,'[^0-9]','','g') THEN
 RAISE EXCEPTION 'H15_CNPJ_MISMATCH' USING ERRCODE='23514'; END IF;
 IF NEW.company_snapshot IS NOT NULL AND NEW.company_snapshot <> '{}'::jsonb THEN
 IF NOT (NEW.company_snapshot ? 'cnpj') OR NULLIF(NEW.company_snapshot->>'cnpj','') IS NULL THEN RAISE EXCEPTION 'H15_SNAPSHOT_CNPJ_REQUIRED' USING ERRCODE='23514'; END IF;
 IF jsonb_typeof(NEW.company_snapshot)<>'object' THEN RAISE EXCEPTION 'H15_SNAPSHOT_INVALID' USING ERRCODE='23514'; END IF;
 -- All identity fields supplied must agree; absent fields remain draft pendencies.
 FOR k IN SELECT jsonb_object_keys(NEW.company_snapshot) LOOP
 actual:=NEW.company_snapshot->>k;
 expected:=CASE k WHEN 'cnpj' THEN c.cnpj WHEN 'legalName' THEN c.legal_name WHEN 'ie' THEN c.state_registration WHEN 'uf' THEN c.state WHEN 'municipalityIbge' THEN c.municipality_ibge_code WHEN 'series' THEN c.nfe_series_number::text WHEN 'environment' THEN c.nfe_environment_code WHEN 'legal_name' THEN c.legal_name WHEN 'crt' THEN c.crt WHEN 'state_registration' THEN c.state_registration WHEN 'state' THEN c.state WHEN 'municipality_ibge_code' THEN c.municipality_ibge_code WHEN 'nfe_series' THEN c.nfe_series::text WHEN 'nfse_series' THEN c.nfse_series::text WHEN 'fiscal_environment' THEN c.fiscal_environment ELSE NULL END;
 IF k IN ('legalName','ie','uf','municipalityIbge','series','environment','cnpj','legal_name','crt','state_registration','state','municipality_ibge_code','nfe_series','nfse_series','fiscal_environment') AND actual IS DISTINCT FROM expected THEN
 RAISE EXCEPTION 'H15_SNAPSHOT_MISMATCH:%',k USING ERRCODE='23514'; END IF;
 END LOOP;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.h15_related_company(p_table text, p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c uuid;
BEGIN
 CASE p_table
 WHEN 'company_fiscal_settings' THEN SELECT id INTO c FROM public.company_fiscal_settings WHERE id=p_id;
 WHEN 'fiscal_invoices' THEN SELECT company_settings_id INTO c FROM public.fiscal_invoices WHERE id=p_id;
 WHEN 'fiscal_certificates' THEN SELECT company_settings_id INTO c FROM public.fiscal_certificates WHERE id=p_id;
 WHEN 'fiscal_document_series' THEN SELECT company_id INTO c FROM public.fiscal_document_series WHERE id=p_id;
 WHEN 'fiscal_invoice_items' THEN SELECT i.company_settings_id INTO c FROM public.fiscal_invoice_items r JOIN public.fiscal_invoices i ON i.id=r.fiscal_invoice_id WHERE r.id=p_id;
 WHEN 'fiscal_events' THEN SELECT i.company_settings_id INTO c FROM public.fiscal_events r JOIN public.fiscal_invoices i ON i.id=r.fiscal_invoice_id WHERE r.id=p_id;
 WHEN 'fiscal_xml_runs' THEN SELECT i.company_settings_id INTO c FROM public.fiscal_xml_runs r JOIN public.fiscal_invoices i ON i.id=r.fiscal_invoice_id WHERE r.id=p_id;
 WHEN 'fiscal_number_reservations' THEN SELECT i.company_settings_id INTO c FROM public.fiscal_number_reservations r JOIN public.fiscal_invoices i ON i.id=r.fiscal_invoice_id WHERE r.id=p_id;
 WHEN 'fiscal_sefaz_transmissions' THEN
 SELECT coalesce(i.company_settings_id,xi.company_settings_id,ei.company_settings_id) INTO c
 FROM public.fiscal_sefaz_transmissions r
 LEFT JOIN public.fiscal_invoices i ON i.id=r.fiscal_invoice_id
 LEFT JOIN public.fiscal_xml_runs x ON x.id=r.xml_run_id
 LEFT JOIN public.fiscal_invoices xi ON xi.id=x.fiscal_invoice_id
 LEFT JOIN public.fiscal_events e ON e.id=r.fiscal_event_id
 LEFT JOIN public.fiscal_invoices ei ON ei.id=e.fiscal_invoice_id
 WHERE r.id=p_id;
 ELSE RAISE EXCEPTION 'H15_UNKNOWN_RELATION' USING ERRCODE='23514';
 END CASE;
 RETURN c;
END $function$

CREATE OR REPLACE FUNCTION public.h15_related_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE data jsonb:=to_jsonb(NEW); old_data jsonb; owner_company uuid; linked uuid; n integer; target uuid;
BEGIN
 IF TG_OP='UPDATE' THEN old_data:=to_jsonb(OLD);
 IF data->TG_ARGV[0] IS DISTINCT FROM old_data->TG_ARGV[0] THEN RAISE EXCEPTION 'H15_PARENT_IMMUTABLE' USING ERRCODE='23514'; END IF;
 END IF;
 target:=nullif(data->>TG_ARGV[0],'')::uuid;
 -- Only technical idempotency operations may have no invoice at all.
 IF TG_TABLE_NAME='fiscal_idempotency_keys' AND target IS NULL THEN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'H15_TECHNICAL_OPERATION_REQUIRED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
 END IF;
 IF TG_TABLE_NAME<>'fiscal_sefaz_transmissions' THEN
 owner_company:=public.h15_related_company(TG_ARGV[1],target);
 IF owner_company IS NULL THEN RAISE EXCEPTION 'H15_PARENT_REQUIRED' USING ERRCODE='23514'; END IF;
 END IF;
 -- Transmissions derive their issuer from the first non-null link, not argument zero.
 n:=0;
 WHILE n<TG_NARGS LOOP
 target:=nullif(data->>TG_ARGV[n],'')::uuid;
 IF target IS NOT NULL THEN
 linked:=public.h15_related_company(TG_ARGV[n+1],target);
 IF linked IS NULL THEN RAISE EXCEPTION 'H15_PARENT_REQUIRED' USING ERRCODE='23514'; END IF;
 IF owner_company IS NULL THEN owner_company:=linked; END IF;
 IF linked IS DISTINCT FROM owner_company THEN RAISE EXCEPTION 'H15_CROSS_COMPANY_REFERENCE:%',TG_ARGV[n] USING ERRCODE='23514'; END IF;
 END IF;
 n:=n+2;
 END LOOP;
 IF owner_company IS NULL THEN RAISE EXCEPTION 'H15_PARENT_REQUIRED' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='fiscal_sefaz_transmissions' AND TG_OP='UPDATE' THEN
 IF owner_company IS DISTINCT FROM public.h15_related_company('fiscal_sefaz_transmissions',OLD.id) THEN RAISE EXCEPTION 'H15_PARENT_IMMUTABLE' USING ERRCODE='23514'; END IF;
 END IF;
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' THEN PERFORM public.h15_require_company(owner_company); END IF;
 RETURN NEW;
END $function$

