AS $function$
DECLARE v_plan uuid; v_status text;
BEGIN
  SELECT plan_id,status INTO v_plan,v_status FROM public.saas_plan_versions WHERE id=COALESCE(NEW.plan_version_id,OLD.plan_version_id);
