$function$

CREATE OR REPLACE FUNCTION public.guard_financial_document_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_org uuid; v_parent_org uuid; v_uid uuid := auth.uid();
  v_path text; v_bucket text; v_parts text[]; v_soft_delete boolean := false;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id
      OR NEW.owner_type IS DISTINCT FROM OLD.owner_type
      OR NEW.owner_id IS DISTINCT FROM OLD.owner_id
      OR NEW.uploaded_by IS DISTINCT FROM OLD.uploaded_by THEN
      RAISE EXCEPTION 'financial_document_identity_immutable' USING ERRCODE = '42501';
    END IF;
    v_soft_delete := OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL
      AND (to_jsonb(NEW) - ARRAY['deleted_at','deleted_by','delete_reason'])
        = (to_jsonb(OLD) - ARRAY['deleted_at','deleted_by','delete_reason']);
    IF (NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
      OR NEW.deleted_by IS DISTINCT FROM OLD.deleted_by
      OR NEW.delete_reason IS DISTINCT FROM OLD.delete_reason) AND NOT v_soft_delete THEN
      RAISE EXCEPTION 'financial_document_tombstone_immutable' USING ERRCODE = '42501';
    END IF;
  END IF;
  IF NEW.organization_id IS NULL THEN
    RAISE EXCEPTION 'financial_document_tenant_required' USING ERRCODE = '42501';
  END IF;
  IF v_uid IS NOT NULL THEN
    v_org := public.h15_actor_organization();
    IF v_org IS NULL OR v_org <> NEW.organization_id OR NOT public.is_financial_staff(v_uid) THEN
      RAISE EXCEPTION 'financial_document_actor_denied' USING ERRCODE = '42501';
    END IF;
    IF TG_OP = 'INSERT' AND NEW.uploaded_by IS DISTINCT FROM v_uid THEN
      RAISE EXCEPTION 'financial_document_author_denied' USING ERRCODE = '42501';
    END IF;
    IF v_soft_delete AND (NEW.deleted_by IS DISTINCT FROM v_uid
      OR length(btrim(coalesce(NEW.delete_reason, ''))) NOT BETWEEN 1 AND 500) THEN
      RAISE EXCEPTION 'financial_document_tombstone_denied' USING ERRCODE = '42501';
    END IF;
  ELSIF NOT (current_setting('role', true) = 'service_role'
    OR (current_setting('role', true) = 'none' AND session_user = 'postgres')) THEN
    RAISE EXCEPTION 'financial_document_actor_required' USING ERRCODE = '42501';
  END IF;
  CASE NEW.owner_type
    WHEN 'RECEIVABLE' THEN SELECT organization_id INTO v_parent_org FROM public.accounts_receivable WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'PAYABLE' THEN SELECT organization_id INTO v_parent_org FROM public.accounts_payable WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'DELIVERY' THEN SELECT organization_id INTO v_parent_org FROM public.entregas WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'FISCAL_INVOICE' THEN SELECT organization_id INTO v_parent_org FROM public.fiscal_invoices WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'PAYMENT_RECEIVABLE' THEN SELECT organization_id INTO v_parent_org FROM public.receivable_payments WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'PAYMENT_PAYABLE' THEN SELECT organization_id INTO v_parent_org FROM public.payable_payments WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'FINANCIAL_RECEIPT' THEN SELECT organization_id, storage_path, storage_bucket INTO v_parent_org, v_path, v_bucket FROM public.financial_receipts WHERE id = NEW.owner_id FOR SHARE;
    WHEN 'REPORT_EXPORT' THEN SELECT organization_id, storage_path, storage_bucket INTO v_parent_org, v_path, v_bucket FROM public.financial_report_exports WHERE id = NEW.owner_id FOR SHARE;
    ELSE RAISE EXCEPTION 'financial_document_owner_denied' USING ERRCODE = '42501';
  END CASE;
  IF v_parent_org IS NULL OR v_parent_org <> NEW.organization_id THEN
    RAISE EXCEPTION 'financial_document_owner_denied' USING ERRCODE = '42501';
  END IF;
  IF NEW.fiscal_invoice_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.fiscal_invoices WHERE id = NEW.fiscal_invoice_id AND organization_id = NEW.organization_id
  ) THEN RAISE EXCEPTION 'financial_document_fiscal_reference_denied' USING ERRCODE = '42501'; END IF;
  IF NEW.fiscal_event_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.fiscal_events WHERE id = NEW.fiscal_event_id AND organization_id = NEW.organization_id
  ) THEN RAISE EXCEPTION 'financial_document_fiscal_reference_denied' USING ERRCODE = '42501'; END IF;
  -- Preserve canonical tombstoning of an unchanged legacy locator. Owner/tenant
  -- and identity still must be valid; NULL-tenant legacy never passes.
  IF v_soft_delete THEN RETURN NEW; END IF;
  IF NOT coalesce(public.storage1_path_strict(NEW.storage_path), false) THEN
    RAISE EXCEPTION 'financial_document_path_denied' USING ERRCODE = '42501';
  END IF;
  v_parts := string_to_array(NEW.storage_path, '/');
  IF NEW.owner_type IN ('FINANCIAL_RECEIPT','REPORT_EXPORT') THEN
    IF v_path IS NULL OR NEW.storage_path IS DISTINCT FROM v_path
      OR v_parts[1] <> NEW.organization_id::text
      OR v_bucket IS DISTINCT FROM (CASE WHEN NEW.owner_type = 'FINANCIAL_RECEIPT' THEN 'financial-receipts' ELSE 'financial-reports' END) THEN
      RAISE EXCEPTION 'financial_document_path_denied' USING ERRCODE = '42501';
    END IF;
  ELSIF array_length(v_parts, 1) <> 3 OR v_parts[1] <> NEW.owner_type
    OR v_parts[2] <> NEW.owner_id::text OR length(v_parts[3]) = 0 THEN
    RAISE EXCEPTION 'financial_document_path_denied' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.guard_manual_cq_write_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE cid uuid; lid uuid; p public.programacao_producao%ROWTYPE; org uuid;
BEGIN
 lid:=CASE WHEN TG_OP='DELETE' THEN OLD.lote_id ELSE NEW.lote_id END;
 SELECT pp.* INTO p FROM public.programacao_producao pp JOIN public.lotes l ON l.programacao_id=pp.id WHERE l.id=lid;
 IF p.ordem_servico_id IS NOT NULL OR p.id IS NULL OR (TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.lotes l JOIN public.programacao_producao pp ON pp.id=l.programacao_id WHERE l.id=OLD.lote_id AND pp.ordem_servico_id IS NOT NULL)) THEN
  org:=platform_private.h15_actor_organization();
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'CQ_MANUAL_REQUIRES_REVIEWED_RPC' USING ERRCODE='42501'; END IF;
  IF auth.uid() IS NULL OR org IS NULL OR public.technical_actor_ready(auth.uid()) IS NOT TRUE
   OR p.organization_id IS DISTINCT FROM org OR NEW.organization_id IS DISTINCT FROM org
   OR p.ordem_servico_onfarm_id IS NOT NULL OR NEW.resultado IS NULL
   OR NEW.responsavel IS DISTINCT FROM 'DADOS FICTICIOS SEM VALOR COMERCIAL'
   OR NEW.responsavel_id IS DISTINCT FROM (SELECT id FROM public.profiles WHERE user_id=auth.uid() AND ativo AND organization_id=org)
   OR NOT EXISTS(SELECT 1 FROM public.lotes l JOIN public.ordens_servico o ON o.id=p.ordem_servico_id JOIN public.clientes c ON c.id=o.cliente_id
     WHERE l.id=lid AND l.organization_id=org AND o.organization_id=org AND c.organization_id=org AND o.status::text='em_cq' AND l.status::text='aguardando_cq')
   OR NOT EXISTS(SELECT 1 FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope='manual_cq_insert_v1' AND target=NEW.id)
   THEN RAISE EXCEPTION 'CQ_MANUAL_REQUIRES_REVIEWED_RPC' USING ERRCODE='42501'; END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION platform_private.guard_manual_cq_parent_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ticket text; org uuid; linked boolean;
BEGIN
 IF TG_TABLE_NAME='ordens_servico' THEN
  linked:=EXISTS(SELECT 1 FROM public.programacao_producao p JOIN public.lotes l ON l.programacao_id=p.id WHERE p.ordem_servico_id=OLD.id AND l.organization_id IS NOT NULL);
  IF linked AND OLD.status::text='em_cq' AND
   (to_jsonb(NEW)-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'updated_at') THEN
   RAISE EXCEPTION 'CQ_MANUAL_PARENT_REQUIRES_REVIEWED_RPC' USING ERRCODE='42501';
  END IF;
  IF linked AND (OLD.status::text='em_cq' OR NEW.status::text='em_cq') AND NEW.status IS DISTINCT FROM OLD.status THEN
   IF OLD.status::text IS DISTINCT FROM 'programada' OR NEW.status::text IS DISTINCT FROM 'em_cq'
    OR (to_jsonb(NEW)-'status'-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'updated_at')
    OR NOT EXISTS(SELECT 1 FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope='manual_cq_send_v1' AND target=OLD.id)
   THEN RAISE EXCEPTION 'CQ_MANUAL_PARENT_REQUIRES_REVIEWED_RPC' USING ERRCODE='42501'; END IF;
  END IF;
 ELSE
  linked:=OLD.ordem_servico_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.lotes l WHERE l.programacao_id=OLD.id AND l.organization_id IS NOT NULL);
  IF linked AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.ordem_servico_id IS DISTINCT FROM OLD.ordem_servico_id
   OR NEW.ordem_servico_onfarm_id IS DISTINCT FROM OLD.ordem_servico_onfarm_id
   OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
   OR NEW.produto_id IS DISTINCT FROM OLD.produto_id OR NEW.microrganismo_id IS DISTINCT FROM OLD.microrganismo_id) THEN
   RAISE EXCEPTION 'CQ_MANUAL_PARENT_REQUIRES_REVIEWED_RPC' USING ERRCODE='42501';
  END IF;
  IF linked AND (OLD.status::text IN ('aguardando_cq','aprovado') OR NEW.status::text IN ('aguardando_cq','aprovado')) AND NEW IS DISTINCT FROM OLD THEN
   ticket:=CASE WHEN OLD.status::text='aguardando' AND NEW.status::text='aguardando_cq' THEN 'manual_cq_send_v1'
     WHEN OLD.status::text='aguardando_cq' AND NEW.status::text='aprovado' THEN 'manual_cq_aprovado_v1' END;
   IF ticket IS NULL OR (to_jsonb(NEW)-'status'-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'updated_at')
    OR NOT EXISTS(SELECT 1 FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope=ticket AND target=OLD.id)
   THEN RAISE EXCEPTION 'CQ_MANUAL_PARENT_REQUIRES_REVIEWED_RPC' USING ERRCODE='42501'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.catalog_family_label_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.classe_catalogo IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE'
     AND NEW.classe_catalogo IS NOT DISTINCT FROM OLD.classe_catalogo
     AND NEW.familia_catalogo IS NOT DISTINCT FROM OLD.familia_catalogo THEN
    RETURN NEW;
  END IF;
  IF NEW.familia_catalogo IS NULL
     OR NOT platform_private.catalog_family_label_check(NEW.familia_catalogo, NEW.classe_catalogo) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'catalog_label_not_active';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.global_product_fiscal_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT platform_private.global_product_fiscal_write_ready() THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.is_active IS NOT TRUE THEN RAISE EXCEPTION 'FISCAL_HISTORY_IMMUTABLE' USING ERRCODE='42501'; END IF;
  IF NEW.product_id IS DISTINCT FROM OLD.product_id OR NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'FISCAL_IDENTITY_IMMUTABLE'; END IF;
  -- Server-owned CAS token for ALL direct editor and IBS/CBS updates.
  -- Strictly newer even inside one transaction; caller timestamps are ignored.
  -- The existing AFTER fiscal audit observes this token in the same transaction.
  NEW.updated_at:=greatest(clock_timestamp(),OLD.updated_at+interval '1 microsecond');
 ELSE NEW.updated_at:=clock_timestamp(); END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.global_product_fiscal_statement_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_WHEN<>'BEFORE' OR TG_LEVEL<>'STATEMENT' OR TG_OP NOT IN ('INSERT','UPDATE') OR TG_RELID<>'public.product_fiscal_profiles'::regclass THEN RAISE EXCEPTION 'invalid_fiscal_guard_context' USING ERRCODE='42501'; END IF;
 IF current_setting('role',true) IN ('anon','authenticated') AND auth.uid() IS NULL THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_GATE_UNAVAILABLE' USING ERRCODE='PT503'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2p1_assignment_fence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'C2P1_ASSIGNMENT_DELETE_CLOSED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=auth.uid() FOR SHARE NOWAIT;
 PERFORM 1 FROM public.user_roles WHERE user_id=auth.uid() ORDER BY role FOR SHARE NOWAIT;
 PERFORM 1 FROM public.organizations WHERE id IN (public.h15_actor_organization(),
 (SELECT commercial_owner_organization_id FROM public.partner_accounts WHERE id=NEW.partner_id),
 (SELECT organization_id FROM public.clientes WHERE id=NEW.customer_id)) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.partner_accounts WHERE id IN (NEW.partner_id,CASE WHEN TG_OP='UPDATE' THEN OLD.partner_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.clientes WHERE id IN (NEW.customer_id,CASE WHEN TG_OP='UPDATE' THEN OLD.customer_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 IF TG_OP='UPDATE' AND NOT platform_private.c2p1_assignment_allowed(OLD.buyer_scope,OLD.partner_id,OLD.customer_id)
 THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NOT platform_private.c2p1_assignment_allowed(NEW.buyer_scope,NEW.partner_id,NEW.customer_id)
 THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2p1_item_fence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.commercial_condition_item_prices;
BEGIN
 IF TG_OP='DELETE' THEN r=OLD; ELSE r=NEW; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=auth.uid() FOR SHARE NOWAIT;
 PERFORM 1 FROM public.user_roles WHERE user_id=auth.uid() ORDER BY role FOR SHARE NOWAIT;
 PERFORM 1 FROM public.organizations WHERE id IN (public.h15_actor_organization(),(SELECT commercial_owner_organization_id FROM public.partner_accounts WHERE id=r.partner_id),(SELECT organization_id FROM public.clientes WHERE id=r.customer_id)) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.partner_accounts WHERE id IN(r.partner_id,CASE WHEN TG_OP='UPDATE' THEN OLD.partner_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.clientes WHERE id IN(r.customer_id,CASE WHEN TG_OP='UPDATE' THEN OLD.customer_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.commercial_payment_plan_assignments WHERE id IN(r.assignment_id,CASE WHEN TG_OP='UPDATE' THEN OLD.assignment_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 IF NOT platform_private.c2p1_item_allowed(r.assignment_id,r.plan_id,r.buyer_scope,r.partner_id,r.customer_id)
 OR (TG_OP='UPDATE' AND NOT platform_private.c2p1_item_allowed(OLD.assignment_id,OLD.plan_id,OLD.buyer_scope,OLD.partner_id,OLD.customer_id)) THEN
 RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.created_at IS DISTINCT FROM OLD.created_at) THEN RAISE EXCEPTION 'C2P1_IDENTITY_IMMUTABLE' USING ERRCODE='42501'; END IF;
 IF TG_OP<>'DELETE' AND r.published_rule_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.commercial_price_rules pr WHERE pr.id=r.published_rule_id AND pr.plan_id=r.plan_id AND pr.buyer_scope=r.buyer_scope
 AND pr.partner_id IS NOT DISTINCT FROM r.partner_id AND pr.customer_id IS NOT DISTINCT FROM r.customer_id
 AND pr.product_id IS NOT DISTINCT FROM r.product_id AND pr.microrganismo_id IS NOT DISTINCT FROM r.microrganismo_id
 AND pr.unit_type=r.unit_type AND pr.volume_ml IS NOT DISTINCT FROM r.volume_ml) THEN RAISE EXCEPTION 'C2P1_RULE_LINK_INVALID' USING ERRCODE='42501'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2p1_rule_fence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.commercial_price_rules;
BEGIN
 IF TG_OP='DELETE' THEN r=OLD; ELSE r=NEW; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=auth.uid() FOR SHARE NOWAIT;
 PERFORM 1 FROM public.user_roles WHERE user_id=auth.uid() ORDER BY role FOR SHARE NOWAIT;
 PERFORM 1 FROM public.organizations WHERE id IN (public.h15_actor_organization(),(SELECT commercial_owner_organization_id FROM public.partner_accounts WHERE id=r.partner_id),(SELECT organization_id FROM public.clientes WHERE id=r.customer_id)) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.partner_accounts WHERE id IN(r.partner_id,CASE WHEN TG_OP='UPDATE' THEN OLD.partner_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.clientes WHERE id IN(r.customer_id,CASE WHEN TG_OP='UPDATE' THEN OLD.customer_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 IF NOT platform_private.c2p1_assignment_allowed(r.buyer_scope,r.partner_id,r.customer_id)
 OR (TG_OP='UPDATE' AND NOT platform_private.c2p1_assignment_allowed(OLD.buyer_scope,OLD.partner_id,OLD.customer_id)) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.commercial_condition_item_prices i WHERE i.published_rule_id=OLD.id AND (NEW.id IS DISTINCT FROM OLD.id OR i.plan_id IS DISTINCT FROM NEW.plan_id OR i.buyer_scope IS DISTINCT FROM NEW.buyer_scope OR i.partner_id IS DISTINCT FROM NEW.partner_id OR i.customer_id IS DISTINCT FROM NEW.customer_id OR i.product_id IS DISTINCT FROM NEW.product_id OR i.microrganismo_id IS DISTINCT FROM NEW.microrganismo_id OR i.unit_type IS DISTINCT FROM NEW.unit_type OR i.volume_ml IS DISTINCT FROM NEW.volume_ml)) THEN RAISE EXCEPTION 'C2P1_RULE_LINK_IMMUTABLE' USING ERRCODE='42501'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_owner_order_create_allowed(_uid uuid, _partner uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c jsonb;
BEGIN
  -- c2_ord_writer_v1: nunca confia em parâmetro de uid que não seja o JWT atual.
  IF _uid IS NULL OR _partner IS NULL OR auth.uid() IS DISTINCT FROM _uid THEN RETURN false; END IF;
  -- Gestor B2B vigente (user_roles canônico; revogação remove a linha). Técnico isolado nunca compra.
  IF NOT public.has_role(_uid,'parceiro_b2b'::public.app_role) THEN RETURN false; END IF;
  c := platform_private.b2b_commercial_context();
  IF c IS NULL OR c->>'contract' <> 'C2_MULTIPROFILE_V1' OR c->>'mode' <> 'commercial_owner'
     OR (c->>'partner_id')::uuid IS DISTINCT FROM _partner OR COALESCE((c->>'manager')::boolean,false) IS NOT TRUE THEN
    RETURN false;
  END IF;
  -- Cliente comercial = sem organização própria; tenant dono ativo e coerente com perfil/vínculo.
  IF EXISTS (SELECT 1 FROM public.organizations o WHERE o.partner_account_id = _partner) THEN RETURN false; END IF;
  IF NOT COALESCE(platform_private.b2b_phase1_partner_visible(_partner,true),false) THEN RETURN false; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.partner_users pu
      JOIN public.partner_accounts pa ON pa.id = pu.partner_id
      JOIN public.profiles p ON p.user_id = pu.user_id
      JOIN public.organizations o ON o.id = pa.commercial_owner_organization_id
     WHERE pu.user_id = _uid AND pu.partner_id = _partner
       AND pu.revoked_at IS NULL AND (pu.valid_from IS NULL OR pu.valid_from <= now())
       AND pa.ativo AND pa.deleted_at IS NULL AND o.ativo AND o.status = 'ativa'
       AND (o.partner_account_id IS NULL OR o.partner_account_id = _partner)
       AND p.ativo AND p.organization_id = pu.tenant_id AND pu.tenant_id = o.id
       AND (c->>'tenant_id')::uuid = o.id
       AND public.is_valid_b2b_partner_user(_uid, pa.id)) THEN
    RETURN false;
  END IF;
  RETURN EXISTS (SELECT 1 FROM platform_private.entitlements_for_user(_uid) e WHERE e.feature_key = 'pedidos_b2b')
     AND EXISTS (SELECT 1 FROM platform_private.entitlements_for_user(_uid) e WHERE e.feature_key = 'catalogo_precos');
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_external_origin_assert(s jsonb, partner uuid, client uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE uid uuid:=auth.uid(); org uuid; p public.partner_accounts;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO p FROM public.partner_accounts WHERE id=partner FOR SHARE;
 org:=p.commercial_owner_organization_id;
 IF NOT FOUND OR p.ativo IS NOT TRUE OR p.deleted_at IS NOT NULL OR org IS NULL
 OR NOT EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=org AND o.ativo AND o.status='ativa')
 OR EXISTS(SELECT 1 FROM public.organizations o WHERE o.partner_account_id=partner)
 OR NOT platform_private.c2_external_origin_contract_valid(s)
 OR s->>'organization_id' IS DISTINCT FROM org::text OR s->>'partner_id' IS DISTINCT FROM partner::text
 THEN RAISE EXCEPTION 'C2_EXTERNAL_ORIGIN_DENIED' USING ERRCODE='42501'; END IF;
 IF client IS DISTINCT FROM p.client_id OR (client IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=client AND c.organization_id=org))
 THEN RAISE EXCEPTION 'C2_EXTERNAL_CLIENT_DENIED' USING ERRCODE='42501'; END IF;
 -- Initial writes are authorized only inside the existing canonical create transaction.
 -- Subsequent administration uses P1's active internal owner authority, never buyer roles.
 IF platform_private.has_ticket('c2_external_order_create',partner) THEN
  IF s->>'actor_user_id' IS DISTINCT FROM uid::text OR NOT platform_private.c2_owner_order_create_allowed(uid,partner)
  THEN RAISE EXCEPTION 'C2_EXTERNAL_CREATE_DENIED' USING ERRCODE='42501'; END IF;
  ELSE
  IF public.h15_actor_organization() IS DISTINCT FROM org OR NOT platform_private.c2p1_settings_allowed(partner,true)
  THEN RAISE EXCEPTION 'C2_EXTERNAL_OWNER_DENIED' USING ERRCODE='42501'; END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION platform_private.guard_visit_plan_preservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  old_block text;
  new_block text;
  authorized boolean;
BEGIN
  old_block := substring(coalesce(OLD.observacoes_tecnicas,'') from '\[PLANO DE MONITORAMENTO\].*?\[FIM DO PLANO\]');
  new_block := substring(coalesce(NEW.observacoes_tecnicas,'') from '\[PLANO DE MONITORAMENTO\].*?\[FIM DO PLANO\]');
  IF (coalesce(NEW.observacoes_tecnicas,'') LIKE '%[PLANO DE MONITORAMENTO]%' OR coalesce(NEW.observacoes_tecnicas,'') LIKE '%[FIM DO PLANO]%') AND
    (new_block IS NULL OR length(coalesce(NEW.observacoes_tecnicas,''))-length(replace(coalesce(NEW.observacoes_tecnicas,''),'[PLANO DE MONITORAMENTO]',''))<>length('[PLANO DE MONITORAMENTO]') OR
      length(coalesce(NEW.observacoes_tecnicas,''))-length(replace(coalesce(NEW.observacoes_tecnicas,''),'[FIM DO PLANO]',''))<>length('[FIM DO PLANO]')) THEN
    RAISE EXCEPTION 'ambiguous_plan_text' USING ERRCODE='PT409';
  END IF;
  IF old_block IS NOT DISTINCT FROM new_block AND (old_block IS NULL OR OLD.data_proxima_visita IS NOT DISTINCT FROM NEW.data_proxima_visita) THEN
    RETURN NEW;
  END IF;
  SELECT EXISTS(SELECT 1 FROM platform_private.visit_plan_write_tickets t
    WHERE t.transaction_id=txid_current() AND t.registro_id=OLD.id
      AND t.block IS NOT DISTINCT FROM new_block AND t.next_date IS NOT DISTINCT FROM NEW.data_proxima_visita)
    INTO authorized;
  IF NOT authorized THEN
    RAISE EXCEPTION 'monitoring_plan_requires_canonical_save' USING ERRCODE='PT409';
  END IF;
  RETURN NEW;
END;
$function$
